PathwayData.put("data/reading_writing/units/L02U4.json",{"strand":"reading_writing","level":2,"cefr":"A1b","unit":4,"theme":"Clothes for Every Day","essential_question":"Why do we wear different clothes?","schema_version":"1.0","core_words":["shirt","pants","shoes","socks","hat","jacket","thobe","scarf","uniform","clean","wear","put on","take off","fold"],"recycled_words":["hot","cold","sunny","rainy","white","blue","big","small","because","school","family","happy","new"],"rubrics":[{"id":"RW-RUBRIC-5T","title":"Analytic writing rubric","traits":[{"name":"Ideas","name_ar":"الأفكار","bands":[{"score":4,"descriptor":"My ideas are clear, interesting and fully developed with strong details.","descriptor_ar":"أفكاري واضحة وممتعة ومدعومة بتفاصيل قوية."},{"score":3,"descriptor":"My ideas are clear and have enough details.","descriptor_ar":"أفكاري واضحة ومعها تفاصيل كافية."},{"score":2,"descriptor":"My main idea is there but needs more details.","descriptor_ar":"فكرتي الرئيسية موجودة لكنها تحتاج إلى تفاصيل أكثر."},{"score":1,"descriptor":"My ideas are unclear or very few.","descriptor_ar":"أفكاري غير واضحة أو قليلة جدًا."}]},{"name":"Organization","name_ar":"التنظيم","bands":[{"score":4,"descriptor":"Clear beginning, middle and end; ideas flow with linking words.","descriptor_ar":"بداية ووسط ونهاية واضحة، والأفكار مترابطة بكلمات الربط."},{"score":3,"descriptor":"Clear order with some linking words.","descriptor_ar":"ترتيب واضح مع بعض كلمات الربط."},{"score":2,"descriptor":"Some order, but parts are mixed up.","descriptor_ar":"يوجد بعض الترتيب لكن بعض الأجزاء غير مرتبة."},{"score":1,"descriptor":"Ideas are not in order.","descriptor_ar":"الأفكار غير مرتبة."}]},{"name":"Vocabulary","name_ar":"المفردات","bands":[{"score":4,"descriptor":"I use exact, varied words, including new unit words, correctly.","descriptor_ar":"أستخدم كلمات دقيقة ومتنوعة، منها كلمات الوحدة الجديدة، بشكل صحيح."},{"score":3,"descriptor":"I use some new words correctly.","descriptor_ar":"أستخدم بعض الكلمات الجديدة بشكل صحيح."},{"score":2,"descriptor":"I use simple words; some are repeated or wrong.","descriptor_ar":"أستخدم كلمات بسيطة، وبعضها مكرر أو غير صحيح."},{"score":1,"descriptor":"I use very few words; the meaning is hard to understand.","descriptor_ar":"أستخدم كلمات قليلة جدًا ويصعب فهم المعنى."}]},{"name":"Sentence fluency","name_ar":"سلاسة الجمل","bands":[{"score":4,"descriptor":"My sentences are complete, varied in length and easy to read aloud.","descriptor_ar":"جملي كاملة ومتنوعة الطول وسهلة القراءة بصوت عالٍ."},{"score":3,"descriptor":"Most sentences are complete, with some variety.","descriptor_ar":"معظم جملي كاملة مع بعض التنويع."},{"score":2,"descriptor":"Many sentences are short or start the same way.","descriptor_ar":"كثير من جملي قصيرة أو تبدأ بالطريقة نفسها."},{"score":1,"descriptor":"Sentences are incomplete or run together.","descriptor_ar":"جملي ناقصة أو متداخلة."}]},{"name":"Conventions","name_ar":"قواعد الكتابة","bands":[{"score":4,"descriptor":"Capitals, punctuation, spelling and grammar are almost always correct.","descriptor_ar":"الحروف الكبيرة وعلامات الترقيم والإملاء والقواعد صحيحة دائمًا تقريبًا."},{"score":3,"descriptor":"A few mistakes that do not affect meaning.","descriptor_ar":"أخطاء قليلة لا تؤثر في المعنى."},{"score":2,"descriptor":"Several mistakes; the meaning is sometimes unclear.","descriptor_ar":"عدة أخطاء، والمعنى أحيانًا غير واضح."},{"score":1,"descriptor":"Many mistakes make it hard to read.","descriptor_ar":"أخطاء كثيرة تجعل القراءة صعبة."}]}]}],"lessons":[{"id":"RW-L02-U4-LS1","title":"Word Power: Clothes for Every Day","lesson_type":"vocabulary","objectives":["read and say 14 words about clothes and 2 Tier 2 words (describe, material)","describe clothes by color, size and material (a long white thobe, a wool scarf)","use put on, take off, wear and fold in sentences about daily routines"],"objectives_ar":["قراءة ونطق 14 كلمة عن الملابس وكلمتين أكاديميتين (describe, material).","وصف الملابس باللون والحجم والمادة.","استخدام put on وtake off وwear وfold في جمل عن الروتين اليومي."],"success_criteria":["I can read and say the clothes words.","I can describe clothes by color, size and material.","I can say what I put on and take off."],"success_criteria_ar":["أستطيع قراءة كلمات الملابس ونطقها.","أستطيع وصف الملابس باللون والحجم والمادة.","أستطيع قول ما ألبسه وما أخلعه."],"map_area":"Vocabulary: Acquisition and Use","vocabulary":[{"word":"shirt","pos":"noun","ipa":"/ʃɝt/","definition":"clothes for the top of your body, often with buttons","arabic":"قميص","example":"Sami wears a white shirt to school.","image_id":"IMG-RW-L02-U4-LS1-V01","audio_id":"AUD-RW-L02-U4-LS1-V01","tier":"core"},{"word":"pants","pos":"noun","ipa":"/pænts/","definition":"clothes for your legs (American English)","arabic":"بنطال / سروال","example":"My pants are gray.","image_id":"IMG-RW-L02-U4-LS1-V02","audio_id":"AUD-RW-L02-U4-LS1-V02","tier":"core"},{"word":"shoes","pos":"noun","ipa":"/ʃuz/","definition":"things you wear on your feet","arabic":"حذاء","example":"Take off your shoes at the door.","image_id":"IMG-RW-L02-U4-LS1-V03","audio_id":"AUD-RW-L02-U4-LS1-V03","tier":"core"},{"word":"socks","pos":"noun","ipa":"/sɑks/","definition":"soft things you wear on your feet under shoes","arabic":"جوارب","example":"I put on clean socks every day.","image_id":"IMG-RW-L02-U4-LS1-V04","audio_id":"AUD-RW-L02-U4-LS1-V04","tier":"core"},{"word":"hat","pos":"noun","ipa":"/hæt/","definition":"a thing you wear on your head","arabic":"قبعة","example":"Wear a hat in the sun.","image_id":"IMG-RW-L02-U4-LS1-V05","audio_id":"AUD-RW-L02-U4-LS1-V05","tier":"core"},{"word":"jacket","pos":"noun","ipa":"/ˈdʒækɪt/","definition":"a short coat","arabic":"سترة / جاكيت","example":"It is cold. Put on your jacket.","image_id":"IMG-RW-L02-U4-LS1-V06","audio_id":"AUD-RW-L02-U4-LS1-V06","tier":"core"},{"word":"thobe","pos":"noun","ipa":"/θoʊb/","definition":"a long robe worn by men and boys in Saudi Arabia","arabic":"ثوب","example":"Grandpa Saleh wears a white thobe.","image_id":"IMG-RW-L02-U4-LS1-V07","audio_id":"AUD-RW-L02-U4-LS1-V07","tier":"core"},{"word":"scarf","pos":"noun","ipa":"/skɑrf/","definition":"a long piece of cloth you wear around your neck","arabic":"وشاح / لفاع","example":"Layla has a soft blue scarf.","image_id":"IMG-RW-L02-U4-LS1-V08","audio_id":"AUD-RW-L02-U4-LS1-V08","tier":"core"},{"word":"uniform","pos":"noun","ipa":"/ˈjunəfɔrm/","definition":"the same clothes that all students or workers wear","arabic":"زي موحد","example":"We wear our uniform at school.","image_id":"IMG-RW-L02-U4-LS1-V09","audio_id":"AUD-RW-L02-U4-LS1-V09","tier":"core"},{"word":"clean","pos":"adjective","ipa":"/klin/","definition":"not dirty","arabic":"نظيف","example":"Wear clean clothes every day.","image_id":"IMG-RW-L02-U4-LS1-V10","audio_id":"AUD-RW-L02-U4-LS1-V10","tier":"core"},{"word":"wear","pos":"verb","ipa":"/wɛr/","definition":"to have clothes on your body","arabic":"يلبس / يرتدي","example":"I wear a jacket in winter.","image_id":"IMG-RW-L02-U4-LS1-V11","audio_id":"AUD-RW-L02-U4-LS1-V11","tier":"core"},{"word":"put on","pos":"verb","ipa":"/pʊt ɑn/","definition":"to start to wear clothes","arabic":"يلبس (يرتدي الآن)","example":"Put on your shoes, please.","image_id":"IMG-RW-L02-U4-LS1-V12","audio_id":"AUD-RW-L02-U4-LS1-V12","tier":"core"},{"word":"take off","pos":"verb","ipa":"/teɪk ɔf/","definition":"to remove clothes from your body","arabic":"يخلع","example":"Take off your jacket inside.","image_id":"IMG-RW-L02-U4-LS1-V13","audio_id":"AUD-RW-L02-U4-LS1-V13","tier":"core"},{"word":"fold","pos":"verb","ipa":"/foʊld/","definition":"to bend clothes neatly into a small shape","arabic":"يطوي","example":"Noura folds her clothes.","image_id":"IMG-RW-L02-U4-LS1-V14","audio_id":"AUD-RW-L02-U4-LS1-V14","tier":"core"},{"word":"describe","pos":"verb","ipa":"/dɪˈskraɪb/","definition":"to say what something is like","arabic":"يصف","example":"Describe your favorite shirt.","image_id":"IMG-RW-L02-U4-LS1-V15","audio_id":"AUD-RW-L02-U4-LS1-V15","tier":"tier2"},{"word":"material","pos":"noun","ipa":"/məˈtɪriəl/","definition":"what a thing is made of (cotton, wool, leather)","arabic":"مادة / خامة","example":"Wool is a warm material.","image_id":"IMG-RW-L02-U4-LS1-V16","audio_id":"AUD-RW-L02-U4-LS1-V16","tier":"tier2"}],"explanation":{"text":"**Describing words** tell us what clothes look and feel like.\n\nWe can describe **color** (white, blue, black), **size** (big, small, long, short) and **material** – what it is made of (cotton, wool, leather).\n\nIn English, the describing word comes **before** the noun: *a **white** thobe* (not *a thobe white*).","examples":["Color: **a white thobe**, **black shoes**, **a blue scarf**.","Size: **a long thobe**, **a short jacket**, **big shoes**, **small socks**.","Material: **a cotton shirt**, **a wool scarf**, **leather shoes**.","Two describing words: **a long white thobe**, **a warm wool jacket**.","**put on** ↔ **take off**: *Put on your jacket. Take off your shoes.*","**wear**: *I wear my uniform on school days.*","**fold**: *Fold your clean shirt and put it in the drawer.*","**clean** ↔ **dirty**: *My socks are clean. His shoes are dirty.*","Describe a friend's clothes: **Omar wears a green jacket and white sports shoes.**"],"common_errors":["✗ I wear a thobe white. → ✓ I wear a white thobe. (The describing word comes **before** the noun.)","✗ I have blues socks. → ✓ I have blue socks. (Describing words have **no -s**.)","✗ I wear my shoe. → ✓ I wear my shoes. (Shoes, socks and pants are usually **plural**.)","✗ Put your jacket. → ✓ Put on your jacket. (Say **put on**.)","✗ Take out your shoes. → ✓ Take off your shoes. (For clothes, say **take off**.)","✗ I am wearing a trousers. → ✓ I am wearing pants. (No **a** before pants; American English says **pants**.)","✗ Wool is warm material for scarf. → ✓ Wool is a warm material for a scarf. (Use **a** before singular nouns.)"],"arabic":"كلمات الوصف تخبرنا كيف تبدو الملابس: اللون (white) والحجم (long) والمادة (wool).\n\nفي الإنجليزية تأتي الصفة قبل الاسم: a white thobe وليس a thobe white كما في العربية.\n\nالصفة لا تُجمع: blue socks وليس blues socks.\n\nput on (يلبس) عكس take off (يخلع)، وwear تعني يرتدي بشكل عام."},"video":{"script":[{"time":"00:00–00:15","narration":"Let's open Layla's closet! What clothes can we see?","on_screen":"Clothes for Every Day","visual":"Layla opens a colorful closet; clothes wave hello."},{"time":"00:15–00:50","narration":"A shirt, pants, shoes, socks, a hat, a jacket, a thobe, a scarf and a uniform!","on_screen":"shirt · pants · shoes · socks · hat · jacket · thobe · scarf · uniform","visual":"Each item slides out on a hanger with its word."},{"time":"00:50–01:25","narration":"Put on your jacket! Take off your shoes! Wear clean clothes. Fold your shirt!","on_screen":"put on ↔ take off · wear · fold · clean","visual":"Sami acts each action quickly, like a cartoon."},{"time":"01:25–02:05","narration":"Describe it! Color: white. Size: long. Material: cotton. A long white cotton thobe!","on_screen":"color · size · material","visual":"Three paint pots (color), a ruler (size) and fabric swatches (material) fly onto a thobe."},{"time":"02:05–02:30","narration":"The describing word comes BEFORE the noun: a white thobe, not a thobe white!","on_screen":"a white thobe ✔  a thobe white ✘","visual":"Word cards swap places and click into order."},{"time":"02:30–02:45","narration":"Now describe what YOU are wearing today!","on_screen":"Describe your clothes!","visual":"Saqr wears a tiny scarf and winks."}],"captions_ar":["لنفتح خزانة ليلى! ما الملابس التي نراها؟","قميص وبنطال وحذاء وجوارب وقبعة وسترة وثوب ووشاح وزي موحد!","البس سترتك! اخلع حذاءك! ارتدِ ملابس نظيفة. اطوِ قميصك!","صِفها! اللون: أبيض. الحجم: طويل. المادة: قطن. ثوب قطني أبيض طويل!","الصفة تأتي قبل الاسم: a white thobe وليس a thobe white!","والآن صِف ما ترتديه اليوم!"],"voice":"Narrator: American English, cheerful female teacher, speed 0.85. Layla describes clothes in a bright, artistic voice."},"texts":[],"activities":[{"id":"RW-L02-U4-LS1-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the correct word.","instructions_ar":"اختر الكلمة الصحيحة.","items":[{"q":"You wear ___ on your feet under your shoes.","answer":"socks","explanation":"Socks go under shoes.","explanation_ar":"جوارب.","options":["hats","socks","scarves","shirts"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Grandpa Saleh wears a long white ___.","answer":"thobe","explanation":"A thobe is long.","explanation_ar":"ثوب.","options":["thobe","sock","hat","shoe"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"All the students wear the same clothes. They wear a ___.","answer":"uniform","explanation":"Same clothes = uniform.","explanation_ar":"زي موحد.","options":["uniform","scarf","material","jacket"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"It is cold outside. ___ your jacket.","answer":"Put on","explanation":"Cold → put on.","explanation_ar":"البس.","options":["Take off","Fold","Describe","Put on"],"dok":1,"skill":"phrasal verbs","stage":"controlled"},{"q":"We go into the mosque. We ___ our shoes.","answer":"take off","explanation":"Inside the mosque → take off.","explanation_ar":"نخلع.","options":["put on","wear","take off","fold"],"dok":1,"skill":"phrasal verbs","stage":"controlled"},{"q":"Noura makes her shirt small and neat for the drawer. She ___ it.","answer":"folds","explanation":"Fold = make neat and small.","explanation_ar":"تطويه.","options":["wears","folds","kicks","throws"],"dok":1,"skill":"vocabulary","stage":"controlled"}]},{"id":"RW-L02-U4-LS1-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Color, size or material? Choose.","instructions_ar":"لون أم حجم أم مادة؟ اختر.","items":[{"q":"In *a wool scarf*, *wool* tells the ___.","answer":"material","explanation":"Wool is what it is made of.","explanation_ar":"المادة.","options":["color","size","material","number"],"dok":1,"skill":"describing words","stage":"guided"},{"q":"In *a long thobe*, *long* tells the ___.","answer":"size","explanation":"Long is a size word.","explanation_ar":"الحجم.","options":["material","color","name","size"],"dok":1,"skill":"describing words","stage":"guided"},{"q":"Which phrase about a thobe has the right word order?","answer":"a white thobe","explanation":"Describing word before the noun.","explanation_ar":"الصفة قبل الاسم.","options":["a thobe white","a white thobe","thobe a white","white a thobe"],"dok":1,"skill":"word order","stage":"guided"},{"q":"Which word is a material?","answer":"cotton","explanation":"Cotton is a material.","explanation_ar":"قطن.","options":["blue","small","tall","cotton"],"dok":1,"skill":"describing words","stage":"guided"},{"q":"Which phrase about socks is correct?","answer":"blue socks","explanation":"No -s on describing words.","explanation_ar":"دون s على الصفة.","options":["blue socks","blues socks","socks blues","a blue socks"],"dok":2,"skill":"word order","stage":"guided"},{"q":"Which phrase describes a jacket with size AND material?","answer":"a short wool jacket","explanation":"short = size, wool = material.","explanation_ar":"الحجم والمادة.","options":["a jacket","a nice day","a short wool jacket","a red apple"],"dok":2,"skill":"describing words","stage":"guided"}]},{"id":"RW-L02-U4-LS1-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Use the word bank.","instructions_ar":"استخدم بنك الكلمات.","items":[{"q":"Please ________ your favorite toy. Is it big or small?","answer":"describe","explanation":"Describe = say what it is like.","explanation_ar":"صِف.","stage":"freer"},{"q":"Leather is a strong ________ for shoes.","answer":"material","explanation":"What shoes are made of.","explanation_ar":"مادة.","stage":"freer"},{"q":"Wear ________ clothes. Do not wear dirty clothes.","answer":"clean","explanation":"Not dirty.","explanation_ar":"نظيفة.","stage":"freer"},{"q":"I ________ my uniform from Sunday to Thursday.","answer":"wear","explanation":"Have clothes on.","explanation_ar":"أرتدي.","stage":"freer"},{"q":"Omar's new ________ are gray. He wears them with his white shirt.","answer":"pants","explanation":"Clothes for legs.","explanation_ar":"بنطاله.","stage":"freer"},{"q":"Wear a ________ on your head in the hot sun.","answer":"hat","explanation":"On your head.","explanation_ar":"قبعة.","stage":"freer"}]},{"id":"RW-L02-U4-LS1-A4","type":"open","stage":"production","instructions":"Writing: Describe YOUR clothes.","instructions_ar":"صِف ملابسك.","items":[{"q":"Describe one thing you are wearing today (color + noun).","answer":"I am wearing a white shirt.","explanation":"Color before the noun.","explanation_ar":"اللون قبل الاسم.","dok":1,"skill":"describing","stage":"production"},{"q":"Describe your shoes with two describing words.","answer":"I have black leather shoes.","explanation":"Two describing words + noun.","explanation_ar":"صفتان + اسم.","dok":2,"skill":"describing","stage":"production"},{"q":"What do you put on when it is cold?","answer":"I put on my warm wool jacket and a scarf.","explanation":"put on + clothes.","explanation_ar":"put on + ملابس.","dok":2,"skill":"phrasal verbs","stage":"production"},{"q":"What do you take off when you come home? Why?","answer":"I take off my shoes because the floor is clean.","explanation":"take off + because.","explanation_ar":"take off + because.","dok":2,"skill":"connect","stage":"production"}]}],"game":{"name":"Dress the Doll","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Dress-up describe: the app says 'a long white thobe' or 'small red socks'; the child drags the matching clothes onto the character. Correct = the character dances.","Teams of four get a paper doll and a set of clothes cards.","The teacher reads a describing phrase (a short blue jacket).","Teams find the right card and put it on the doll.","The first correct team says the phrase aloud and gets 1 point.","Bonus round: a team describes a card for the class to find."],"data":[]},"exit_quiz":[{"q":"Which word is NOT clothes?","answer":"material","explanation":"Material is what clothes are made of.","explanation_ar":"مادة وليست ملابس.","options":["shirt","jacket","scarf","material"],"dok":1,"skill":"vocabulary"},{"q":"What is the opposite of *put on*?","answer":"take off","explanation":"put on ↔ take off.","explanation_ar":"take off.","options":["wear","take off","fold","clean"],"dok":1,"skill":"opposites"},{"q":"Which phrase about Layla's scarf is in the right order?","answer":"a soft blue scarf","explanation":"Describing words before the noun.","explanation_ar":"الصفات قبل الاسم.","options":["a scarf soft blue","scarf a blue soft","a soft blue scarf","a blue scarf soft"],"dok":1,"skill":"word order"},{"q":"*Wool* and *cotton* are kinds of ___.","answer":"material","explanation":"They are materials.","explanation_ar":"مواد.","options":["material","color","size","shoes"],"dok":1,"skill":"describing words"},{"q":"*Describe your hat.* *Describe* means ___.","answer":"say what it is like","explanation":"Describe = say what it is like.","explanation_ar":"صِف.","options":["take it off","fold it","buy it","say what it is like"],"dok":1,"skill":"vocabulary"},{"q":"Which sentence uses *wear* correctly?","answer":"I wear a hat in the sun.","explanation":"wear + clothes.","explanation_ar":"wear + الملابس.","options":["I wear a hat in the sun.","I wear on a hat.","I wearing hat.","I wear off my hat."],"dok":2,"skill":"usage"},{"q":"Which phrase tells the COLOR and the SIZE of a thobe?","answer":"a long white thobe","explanation":"long = size; white = color.","explanation_ar":"طويل وأبيض.","options":["a cotton thobe","a long white thobe","a thobe","a clean thobe"],"dok":2,"skill":"describing words"},{"q":"Fix it: *I have reds shoes.*","answer":"I have red shoes.","explanation":"No -s on describing words.","explanation_ar":"دون s على الصفة.","options":["I have shoes reds.","I have a red shoes.","I has red shoe.","I have red shoes."],"dok":2,"skill":"editing"},{"q":"Why do we take off our shoes at the mosque?","answer":"to keep the mosque clean","explanation":"Shoes can bring dirt inside.","explanation_ar":"لنحافظ على نظافة المسجد.","options":["because shoes are new","to fold them","to keep the mosque clean","because it is cold"],"dok":2,"skill":"reasoning"},{"q":"Which describing word helps a reader know a jacket is WARM?","answer":"wool","explanation":"Wool is a warm material.","explanation_ar":"الصوف دافئ.","options":["blue","wool","short","new"],"dok":3,"skill":"word choice"}],"images":[{"id":"IMG-RW-L02-U4-LS1-V01","prompt":"Picture for the word 'shirt': a white shirt with buttons"},{"id":"IMG-RW-L02-U4-LS1-V02","prompt":"Picture for the word 'pants': gray school pants"},{"id":"IMG-RW-L02-U4-LS1-V03","prompt":"Picture for the word 'shoes': a pair of black shoes"},{"id":"IMG-RW-L02-U4-LS1-V04","prompt":"Picture for the word 'socks': a pair of striped socks"},{"id":"IMG-RW-L02-U4-LS1-V05","prompt":"Picture for the word 'hat': a straw sun hat"},{"id":"IMG-RW-L02-U4-LS1-V06","prompt":"Picture for the word 'jacket': a navy zip-up jacket"},{"id":"IMG-RW-L02-U4-LS1-V07","prompt":"Picture for the word 'thobe': a long white thobe on a hanger"},{"id":"IMG-RW-L02-U4-LS1-V08","prompt":"Picture for the word 'scarf': a striped wool scarf"},{"id":"IMG-RW-L02-U4-LS1-V09","prompt":"Picture for the word 'uniform': children in matching school uniforms"},{"id":"IMG-RW-L02-U4-LS1-V10","prompt":"Picture for the word 'clean': a neat pile of clean, folded clothes"},{"id":"IMG-RW-L02-U4-LS1-V11","prompt":"Picture for the word 'wear': a child wearing a jacket and hat"},{"id":"IMG-RW-L02-U4-LS1-V12","prompt":"Picture for the word 'put on': a child putting on a shoe"},{"id":"IMG-RW-L02-U4-LS1-V13","prompt":"Picture for the word 'take off': a child taking off a jacket"},{"id":"IMG-RW-L02-U4-LS1-V14","prompt":"Picture for the word 'fold': hands folding a T-shirt"},{"id":"IMG-RW-L02-U4-LS1-V15","prompt":"Picture for the word 'describe': a child pointing to a shirt and talking"},{"id":"IMG-RW-L02-U4-LS1-V16","prompt":"Picture for the word 'material': three swatches: cotton, wool, leather"},{"id":"IMG-RW-L02-U4-LS1-01","prompt":"Characters wearing a school uniform, a thobe, a scarf and sports clothes."},{"id":"IMG-RW-L02-U4-LS1-02","prompt":"A thobe with labels for color, size and material."},{"id":"IMG-RW-L02-U4-LS1-03","prompt":"A boy puts on his shoes and later takes them off at the mosque."}],"audio":[{"id":"AUD-RW-L02-U4-LS1-V01","script":"shirt. Sami wears a white shirt to school."},{"id":"AUD-RW-L02-U4-LS1-V02","script":"pants. My pants are gray."},{"id":"AUD-RW-L02-U4-LS1-V03","script":"shoes. Take off your shoes at the door."},{"id":"AUD-RW-L02-U4-LS1-V04","script":"socks. I put on clean socks every day."},{"id":"AUD-RW-L02-U4-LS1-V05","script":"hat. Wear a hat in the sun."},{"id":"AUD-RW-L02-U4-LS1-V06","script":"jacket. It is cold. Put on your jacket."},{"id":"AUD-RW-L02-U4-LS1-V07","script":"thobe. Grandpa Saleh wears a white thobe."},{"id":"AUD-RW-L02-U4-LS1-V08","script":"scarf. Layla has a soft blue scarf."},{"id":"AUD-RW-L02-U4-LS1-V09","script":"uniform. We wear our uniform at school."},{"id":"AUD-RW-L02-U4-LS1-V10","script":"clean. Wear clean clothes every day."},{"id":"AUD-RW-L02-U4-LS1-V11","script":"wear. I wear a jacket in winter."},{"id":"AUD-RW-L02-U4-LS1-V12","script":"put on. Put on your shoes, please."},{"id":"AUD-RW-L02-U4-LS1-V13","script":"take off. Take off your jacket inside."},{"id":"AUD-RW-L02-U4-LS1-V14","script":"fold. Noura folds her clothes."},{"id":"AUD-RW-L02-U4-LS1-V15","script":"describe. Describe your favorite shirt."},{"id":"AUD-RW-L02-U4-LS1-V16","script":"material. Wool is a warm material."},{"id":"AUD-RW-L02-U4-LS1-VID","script":"Let's open Layla's closet! What clothes can we see? A shirt, pants, shoes, socks, a hat, a jacket, a thobe, a scarf and a uniform! Put on your jacket! Take off your shoes! Wear clean clothes. Fold your shirt! Describe it! Color: white. Size: long. Material: cotton. A long white cotton thobe! The describing word comes BEFORE the noun: a white thobe, not a thobe white! Now describe what YOU are wearing today!"}]},{"id":"RW-L02-U4-LS2","title":"Clothes for Hot and Cold Places","lesson_type":"close_reading","objectives":["read an informational text of about 120 words with headings","ask and answer who, what, where, why and how questions about the text","find the answer in the text and point to the evidence"],"objectives_ar":["قراءة نص معلوماتي من نحو 120 كلمة فيه عناوين فرعية.","طرح أسئلة من/ماذا/أين/لماذا/كيف عن النص والإجابة عنها.","إيجاد الإجابة في النص والإشارة إلى الدليل."],"success_criteria":["I can ask a question about the text.","I can find the answer in the text.","I can use the headings to find information."],"success_criteria_ar":["أستطيع طرح سؤال عن النص.","أستطيع إيجاد الإجابة في النص.","أستطيع استخدام العناوين لإيجاد المعلومات."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"weather","pos":"noun","ipa":"/ˈwɛðər/","definition":"how hot, cold, sunny or rainy it is outside","arabic":"الطقس","example":"The weather is hot today.","image_id":"IMG-RW-L02-U4-LS2-V01","audio_id":"AUD-RW-L02-U4-LS2-V01","tier":"core"},{"word":"loose","pos":"adjective","ipa":"/lus/","definition":"not tight; big on your body","arabic":"فضفاض / واسع","example":"Loose clothes are cool in summer.","image_id":"IMG-RW-L02-U4-LS2-V02","audio_id":"AUD-RW-L02-U4-LS2-V02","tier":"core"},{"word":"thick","pos":"adjective","ipa":"/θɪk/","definition":"not thin; with a lot of material","arabic":"سميك","example":"A thick jacket keeps you warm.","image_id":"IMG-RW-L02-U4-LS2-V03","audio_id":"AUD-RW-L02-U4-LS2-V03","tier":"core"},{"word":"gloves","pos":"noun","ipa":"/ɡlʌvz/","definition":"clothes for your hands","arabic":"قفازات","example":"Wear gloves in the snow.","image_id":"IMG-RW-L02-U4-LS2-V04","audio_id":"AUD-RW-L02-U4-LS2-V04","tier":"core"},{"word":"raincoat","pos":"noun","ipa":"/ˈreɪnkoʊt/","definition":"a coat that keeps the rain off","arabic":"معطف المطر","example":"Put on your raincoat. It is raining.","image_id":"IMG-RW-L02-U4-LS2-V05","audio_id":"AUD-RW-L02-U4-LS2-V05","tier":"core"},{"word":"boots","pos":"noun","ipa":"/buts/","definition":"strong shoes that cover your feet and ankles","arabic":"أحذية طويلة (بوت)","example":"Wear boots in the mud.","image_id":"IMG-RW-L02-U4-LS2-V06","audio_id":"AUD-RW-L02-U4-LS2-V06","tier":"core"},{"word":"snowy","pos":"adjective","ipa":"/ˈsnoʊi/","definition":"with a lot of snow","arabic":"مثلج / كثير الثلج","example":"Canada is snowy in winter.","image_id":"IMG-RW-L02-U4-LS2-V07","audio_id":"AUD-RW-L02-U4-LS2-V07","tier":"core"}],"explanation":{"text":"Good readers **ask questions** and then **look for the answers** in the text.\n\nQuestion words: **Who?** (a person) **What?** (a thing) **Where?** (a place) **Why?** (a reason) **How?** (the way).\n\nUse the **headings** to find the right part fast. Then point to the **exact words** in the text: that is your **evidence**.","examples":["**Where** do people wear light, loose clothes? → in **hot, sunny places** (heading: *Hot places*).","**Who** wears a long white thobe? → **many men and boys**.","**What** do people put on in cold places? → **wool jackets, scarves and two pairs of socks**.","**Why** do people wear hats in hot places? → **so the sun does not burn their heads**.","**Why** do people wear gloves in Canada? → **their hands get very cold**.","**What** do people wear in rainy places? → **raincoats and boots**.","**How** do white clothes help? → they help you **stay cool**.","**What** do we do at home? → we **take off our shoes**.","Make your OWN question: **Which place is snowy?** → **Canada**."],"common_errors":["✗ Where people wear gloves? → ✓ Where do people wear gloves? (Add **do** in the question.)","✗ Why they wear hats? → ✓ Why do they wear hats? (Why + **do** + they + verb.)","✗ Answer: in Canada. (for a 'why' question) → ✓ Answer: because their hands get very cold. (**Why** needs a reason, not a place.)","✗ The people wears thick clothes. → ✓ People wear thick clothes. (People → **wear**.)","✗ In cold place → ✓ In cold places (Many places → **places**.)","✗ I think the answer. (no evidence) → ✓ The text says, 'they wear gloves.' (Point to the words in the text.)"],"arabic":"القارئ الجيد يطرح أسئلة ثم يبحث عن الإجابات في النص.\n\nأدوات الاستفهام: Who (شخص)، What (شيء)، Where (مكان)، Why (سبب)، How (طريقة).\n\nاستخدم العناوين الفرعية لتصل إلى الجزء الصحيح بسرعة، ثم أشر إلى الكلمات نفسها في النص؛ هذا هو دليلك.\n\nانتبه: سؤال Why يحتاج إلى سبب، وسؤال Where يحتاج إلى مكان."},"video":{"script":[{"time":"00:00–00:15","narration":"Sami has a question: Why do people wear different clothes?","on_screen":"Ask a question! ❓","visual":"Sami with a giant question mark above his head, holding a globe."},{"time":"00:15–01:20","narration":"People around the world wear different clothes…","on_screen":"(text, section by section)","visual":"A globe spins to Saudi Arabia (sun, thobe, hat), Canada (snow, jacket, gloves), a rainy city (raincoat, boots), then a cozy home."},{"time":"01:20–01:55","narration":"Who? What? Where? Why? How? Each question word wants a different answer!","on_screen":"Who · What · Where · Why · How","visual":"Five question words light up with icons: person, box, map pin, light bulb, gear."},{"time":"01:55–02:30","narration":"Why do people wear gloves in Canada? Look at the heading 'Cold places'… Their hands get very cold!","on_screen":"Find the evidence 🔍","visual":"A magnifying glass moves over the heading and highlights the sentence."},{"time":"02:30–02:50","narration":"Now YOU ask a question and find the answer!","on_screen":"Ask → Look → Answer","visual":"Saqr wears tiny gloves and shivers, then smiles."}],"captions_ar":["لدى سامي سؤال: لماذا يرتدي الناس ملابس مختلفة؟","يرتدي الناس حول العالم ملابس مختلفة…","من؟ ماذا؟ أين؟ لماذا؟ كيف؟ كل أداة استفهام تحتاج إجابة مختلفة!","لماذا يلبس الناس القفازات في كندا؟ انظر إلى عنوان «الأماكن الباردة»… لأن أيديهم تبرد كثيرًا!","والآن اطرح أنت سؤالًا وابحث عن إجابته!"],"voice":"Narrator: American English, warm female teacher, speed 0.85. Sami (the Questioner) asks questions in a curious voice."},"texts":[{"type":"reading","title":"Clothes for Hot and Cold Places","body":"People around the world wear different clothes. Why? The weather is different!\n\n**Hot places** – In hot, sunny places like Saudi Arabia, people wear light, loose clothes. Many men and boys wear a long white thobe. White clothes help you stay cool. People wear hats, so the sun does not burn their heads.\n\n**Cold places** – In cold, snowy places like Canada, people wear thick, warm clothes. They put on wool jackets, scarves and two pairs of socks. Their hands get very cold, so they wear gloves.\n\n**Rainy places** – In rainy places, people wear raincoats and boots because rain makes clothes wet.\n\n**At home** – At home, we take off our shoes and wear soft, clean clothes.\n\nWhat will you wear today?","word_count":119,"audio_id":"AUD-RW-L02-U4-LS2-T1","id":"TXT-RW-L02-U4-LS2-1","genre":"informational","role":"main","difficulty":"200L–350L","glossary":[{"word":"loose","definition":"not tight; big on your body","arabic":"فضفاض"},{"word":"thick","definition":"big from one side to the other; not thin","arabic":"سميك"},{"word":"gloves","definition":"clothes for your hands","arabic":"قفازات"}]}],"activities":[{"id":"RW-L02-U4-LS2-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read the text. Choose the answer.","instructions_ar":"اقرأ النص واختر الإجابة.","items":[{"q":"Why do people around the world wear different clothes?","answer":"The weather is different.","explanation":"Text: The weather is different!","explanation_ar":"الطقس مختلف.","options":["The weather is different.","They like new colors.","Shops are different.","They play different games."],"dok":1,"skill":"key details","stage":"controlled"},{"q":"Which hot, sunny place does the text name?","answer":"Saudi Arabia","explanation":"Text: like Saudi Arabia.","explanation_ar":"السعودية.","options":["Canada","Saudi Arabia","a rainy city","the beach"],"dok":1,"skill":"key details: where","stage":"controlled"},{"q":"Who wears a long white thobe?","answer":"many men and boys","explanation":"Text: Many men and boys.","explanation_ar":"رجال وأولاد كثيرون.","options":["people in Canada","people in the rain","babies at home","many men and boys"],"dok":1,"skill":"key details: who","stage":"controlled"},{"q":"What do people put on in cold places?","answer":"wool jackets, scarves and two pairs of socks","explanation":"Section: Cold places.","explanation_ar":"سترات صوفية ووشاحات وجوارب.","options":["light, loose clothes","raincoats only","wool jackets, scarves and two pairs of socks","white thobes"],"dok":1,"skill":"key details: what","stage":"controlled"},{"q":"What do people wear in rainy places?","answer":"raincoats and boots","explanation":"Section: Rainy places.","explanation_ar":"معاطف المطر والأحذية الطويلة.","options":["hats and thobes","gloves only","raincoats and boots","nothing on their feet"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What do we take off at home?","answer":"our shoes","explanation":"Section: At home.","explanation_ar":"أحذيتنا.","options":["our shoes","our hats","our gloves","our raincoats"],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L02-U4-LS2-A2","type":"true_false","stage":"guided","instructions":"Guided practice: True or false? Check the text.","instructions_ar":"صح أم خطأ؟ تحقق من النص.","items":[{"q":"In hot places, people wear thick, warm clothes.","answer":"false","explanation":"They wear light, loose clothes.","explanation_ar":"يلبسون ملابس خفيفة فضفاضة.","options":["true","false"],"dok":1,"skill":"key details","text_id":"TXT-RW-L02-U4-LS2-1","stage":"guided"},{"q":"White clothes help you stay cool.","answer":"true","explanation":"Text: White clothes help you stay cool.","explanation_ar":"صحيح.","options":["true","false"],"dok":1,"skill":"key details","stage":"guided"},{"q":"People in Canada wear gloves because their hands get very cold.","answer":"true","explanation":"Section: Cold places.","explanation_ar":"صحيح.","options":["true","false"],"dok":1,"skill":"cause and effect","stage":"guided"},{"q":"Rain makes clothes dry.","answer":"false","explanation":"Rain makes clothes wet.","explanation_ar":"المطر يبلّل الملابس.","options":["true","false"],"dok":1,"skill":"key details","stage":"guided"},{"q":"The heading *Rainy places* tells us about raincoats and boots.","answer":"true","explanation":"That section is about rainy places.","explanation_ar":"صحيح.","options":["true","false"],"dok":2,"skill":"text features","stage":"guided"},{"q":"The text says people wear two pairs of socks in hot places.","answer":"false","explanation":"Two pairs of socks are for cold places.","explanation_ar":"الجوارب المزدوجة للأماكن الباردة.","options":["true","false"],"dok":2,"skill":"key details","stage":"guided"}]},{"id":"RW-L02-U4-LS2-A3","type":"mcq","stage":"freer","instructions":"Freer practice: Which question word? Which heading? Choose.","instructions_ar":"أي أداة استفهام؟ أي عنوان؟ اختر.","items":[{"q":"You want to know the REASON people wear hats. Which question word do you use?","answer":"Why","explanation":"Why asks for a reason.","explanation_ar":"Why للسبب.","options":["Why","Where","Who","What"],"dok":1,"skill":"question words","stage":"freer"},{"q":"Which heading helps you find out about gloves?","answer":"Cold places","explanation":"Gloves are in the cold section.","explanation_ar":"Cold places.","options":["Hot places","Cold places","Rainy places","At home"],"dok":1,"skill":"text features","stage":"freer"},{"q":"Underline the reason people wear hats in hot places.","answer":"People wear hats, so the sun does not burn their heads.","explanation":"This sentence gives the reason.","explanation_ar":"هذه الجملة تعطي السبب.","evidence":"People wear hats, so the sun does not burn their heads.","text_id":"TXT-RW-L02-U4-LS2-1","dok":2,"skill":"evidence","stage":"freer"},{"q":"The text ends with *What will you wear today?* Why?","answer":"to make the reader think about their own clothes","explanation":"A question invites the reader.","explanation_ar":"ليجعل القارئ يفكر في ملابسه.","options":["to tell the reader about Canada","to give a new heading","to make the reader think about their own clothes","to say the text is about rain"],"dok":3,"skill":"author's purpose","stage":"freer"}]},{"id":"RW-L02-U4-LS2-A4","type":"open","stage":"production","instructions":"Writing: Ask and answer.","instructions_ar":"اسأل وأجب.","items":[{"q":"Write a WHERE question about the text. Then answer it.","answer":"Where do people wear boots? In rainy places.","explanation":"Where + answer (a place).","explanation_ar":"Where + مكان.","dok":2,"skill":"asking questions","stage":"production"},{"q":"Write a WHY question about the text. Then answer it.","answer":"Why do people wear white thobes? White clothes help them stay cool.","explanation":"Why + reason.","explanation_ar":"Why + سبب.","dok":2,"skill":"asking questions","stage":"production"},{"q":"What clothes do you wear in Taif in winter?","answer":"I wear a thick jacket and a wool scarf in winter.","explanation":"Describe your clothes.","explanation_ar":"صِف ملابسك.","dok":2,"skill":"connect","stage":"production"},{"q":"Which place in the text would you like to visit? What would you wear?","answer":"I would like to visit Canada. I would wear boots, gloves and a warm jacket.","explanation":"Place + clothes.","explanation_ar":"مكان + ملابس.","dok":3,"skill":"apply","stage":"production"}]},{"id":"RW-L02-U4-LS2-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Clothes for Hot and Cold Places\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Clothes for Hot and Cold Places”.","answer":"119 words","title":"Clothes for Hot and Cold Places","body":"People around the world wear different clothes. Why? The weather is different!\n\n**Hot places** – In hot, sunny places like Saudi Arabia, people wear light, loose clothes. Many men and boys wear a long white thobe. White clothes help you stay cool. People wear hats, so the sun does not burn their heads.\n\n**Cold places** – In cold, snowy places like Canada, people wear thick, warm clothes. They put on wool jackets, scarves and two pairs of socks. Their hands get very cold, so they wear gloves.\n\n**Rainy places** – In rainy places, people wear raincoats and boots because rain makes clothes wet.\n\n**At home** – At home, we take off our shoes and wear soft, clean clothes.\n\nWhat will you wear today?","words":119,"limit":144}],"time_limit_sec":144}],"game":{"name":"Pack the Suitcase","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Travel packer: a plane lands in a hot, snowy or rainy place; the child drags the right clothes into the suitcase, then answers one Why? question to take off again.","Teams get a suitcase card (e.g., Canada in winter).","In 60 seconds, teams pack four clothes cards that match the place.","The teacher asks the team one Who/What/Where/Why question about the text.","Right clothes = 1 point each; right answer with evidence = 2 points.","Swap suitcase cards and play again."],"data":[]},"exit_quiz":[{"q":"What is *Clothes for Hot and Cold Places* mainly about?","answer":"why people wear different clothes in different weather","explanation":"All the sections tell about weather and clothes.","explanation_ar":"لماذا تختلف الملابس باختلاف الطقس.","options":["how to fold clothes","a story about a lost scarf","why people wear different clothes in different weather","how to play in the snow"],"dok":1,"skill":"main topic"},{"q":"You want to know the PLACE where people wear boots. Which question word do you use?","answer":"Where","explanation":"Where = place.","explanation_ar":"Where.","options":["Who","Where","Why","How"],"dok":1,"skill":"question words"},{"q":"You want to know the PERSON who wears a white thobe. Which question word do you use?","answer":"Who","explanation":"Who = person.","explanation_ar":"Who.","options":["Who","Where","What","Why"],"dok":1,"skill":"question words"},{"q":"*Loose clothes are cool.* *Loose* means ___.","answer":"not tight","explanation":"Loose = not tight.","explanation_ar":"فضفاض.","options":["very small","wet","dirty","not tight"],"dok":1,"skill":"vocabulary"},{"q":"Which question about Canada is written correctly?","answer":"Why do people wear gloves in Canada?","explanation":"Why + do + people + verb.","explanation_ar":"ترتيب صحيح.","options":["Why people wear gloves in Canada?","Why wear people gloves in Canada?","People why wear gloves in Canada?","Why do people wear gloves in Canada?"],"dok":2,"skill":"question order"},{"q":"Where in the text can you find out about boots?","answer":"under the heading *Rainy places*","explanation":"Boots are in the rainy section.","explanation_ar":"تحت عنوان Rainy places.","options":["under *Hot places*","under the heading *Rainy places*","in the title only","in the last question"],"dok":1,"skill":"text features"},{"q":"Why does a thick jacket help in Canada?","answer":"It keeps people warm.","explanation":"Thick = warm.","explanation_ar":"يدفئ.","options":["It keeps people cool.","It keeps people warm.","It is white.","It is loose."],"dok":2,"skill":"inference"},{"q":"What is the BEST evidence that the sun can be strong in hot places?","answer":"\"…so the sun does not burn their heads.\"","explanation":"Burn shows the sun is strong.","explanation_ar":"دليل قوة الشمس.","options":["\"…so the sun does not burn their heads.\"","\"People around the world wear different clothes.\"","\"What will you wear today?\"","\"…wear soft, clean clothes.\""],"dok":2,"skill":"evidence"},{"q":"Sami goes to a snowy mountain. What should he take?","answer":"a wool jacket, gloves and boots","explanation":"Snowy = cold.","explanation_ar":"ملابس دافئة.","options":["a light thobe and a sun hat","a swimsuit","only socks","a wool jacket, gloves and boots"],"dok":3,"skill":"apply"},{"q":"Why does the writer use headings?","answer":"to help readers find information fast","explanation":"Headings organize facts.","explanation_ar":"لتسهيل إيجاد المعلومات.","options":["to make the text funny","to tell a story","to help readers find information fast","to list the new words"],"dok":3,"skill":"text features"}],"images":[{"id":"IMG-RW-L02-U4-LS2-V01","prompt":"Picture for the word 'weather': icons of sun, cloud, rain and snow"},{"id":"IMG-RW-L02-U4-LS2-V02","prompt":"Picture for the word 'loose': a child in a loose thobe moving freely"},{"id":"IMG-RW-L02-U4-LS2-V03","prompt":"Picture for the word 'thick': a thin and a thick jacket side by side"},{"id":"IMG-RW-L02-U4-LS2-V04","prompt":"Picture for the word 'gloves': a pair of red wool gloves"},{"id":"IMG-RW-L02-U4-LS2-V05","prompt":"Picture for the word 'raincoat': a yellow raincoat with drops on it"},{"id":"IMG-RW-L02-U4-LS2-V06","prompt":"Picture for the word 'boots': a pair of brown boots"},{"id":"IMG-RW-L02-U4-LS2-V07","prompt":"Picture for the word 'snowy': a snowy street with snowflakes"},{"id":"IMG-RW-L02-U4-LS2-01","prompt":"People in thobes on a sunny street and people in warm clothes on a snowy street."},{"id":"IMG-RW-L02-U4-LS2-02","prompt":"A child in a raincoat and a child relaxing at home."},{"id":"IMG-RW-L02-U4-LS2-03","prompt":"Icons for who, what, where, why and how."}],"audio":[{"id":"AUD-RW-L02-U4-LS2-V01","script":"weather. The weather is hot today."},{"id":"AUD-RW-L02-U4-LS2-V02","script":"loose. Loose clothes are cool in summer."},{"id":"AUD-RW-L02-U4-LS2-V03","script":"thick. A thick jacket keeps you warm."},{"id":"AUD-RW-L02-U4-LS2-V04","script":"gloves. Wear gloves in the snow."},{"id":"AUD-RW-L02-U4-LS2-V05","script":"raincoat. Put on your raincoat. It is raining."},{"id":"AUD-RW-L02-U4-LS2-V06","script":"boots. Wear boots in the mud."},{"id":"AUD-RW-L02-U4-LS2-V07","script":"snowy. Canada is snowy in winter."},{"id":"AUD-RW-L02-U4-LS2-T1","script":"People around the world wear different clothes. Why? The weather is different! **Hot places** – In hot, sunny places like Saudi Arabia, people wear light, loose clothes. Many men and boys wear a long white thobe. White clothes help you stay cool. People wear hats, so the sun does not burn their heads. **Cold places** – In cold, snowy places like Canada, people wear thick, warm clothes. They put on wool jackets, scarves and two pairs of socks. Their hands get very cold, so they wear gloves. **Rainy places** – In rainy places, people wear raincoats and boots because rain makes clothes wet. **At home** – At home, we take off our shoes and wear soft, clean clothes. What will you wear today?"},{"id":"AUD-RW-L02-U4-LS2-VID","script":"Sami has a question: Why do people wear different clothes? People around the world wear different clothes… Who? What? Where? Why? How? Each question word wants a different answer! Why do people wear gloves in Canada? Look at the heading 'Cold places'… Their hands get very cold! Now YOU ask a question and find the answer!"}]},{"id":"RW-L02-U4-LS3","title":"Cause and effect with because and so: \"Uniforms Are a Good Idea\"","lesson_type":"strategy_paired_text","objectives":["find causes and effects in a text using because and so","tell the writer's opinion and reasons in a short opinion text","join a cause and an effect in one sentence with because or so"],"objectives_ar":["إيجاد الأسباب والنتائج في النص باستخدام because وso.","تحديد رأي الكاتب وأسبابه في نص رأي قصير.","ربط السبب بالنتيجة في جملة واحدة بـ because أو so."],"success_criteria":["I can find a cause and its effect.","I can use because before a cause and so before an effect.","I can tell Sami's opinion and one reason."],"success_criteria_ar":["أستطيع إيجاد السبب ونتيجته.","أستطيع استخدام because قبل السبب وso قبل النتيجة.","أستطيع ذكر رأي سامي وسببًا واحدًا."],"map_area":"Informational Text: Key Ideas and Details","vocabulary":[{"word":"cause","pos":"noun","ipa":"/kɔz/","definition":"why something happens","arabic":"سبب","example":"The rain is the cause. Our clothes are wet.","image_id":"IMG-RW-L02-U4-LS3-V01","audio_id":"AUD-RW-L02-U4-LS3-V01","tier":"core"},{"word":"effect","pos":"noun","ipa":"/ɪˈfɛkt/","definition":"what happens because of something","arabic":"نتيجة / أثر","example":"Wet clothes are the effect of the rain.","image_id":"IMG-RW-L02-U4-LS3-V02","audio_id":"AUD-RW-L02-U4-LS3-V02","tier":"core"},{"word":"so","pos":"conjunction","ipa":"/soʊ/","definition":"a word that joins a cause to its effect","arabic":"لذلك / لذا","example":"It is cold, so I put on my jacket.","image_id":"IMG-RW-L02-U4-LS3-V03","audio_id":"AUD-RW-L02-U4-LS3-V03","tier":"core"},{"word":"opinion","pos":"noun","ipa":"/əˈpɪnjən/","definition":"what you think or feel about something","arabic":"رأي","example":"In my opinion, uniforms are good.","image_id":"IMG-RW-L02-U4-LS3-V04","audio_id":"AUD-RW-L02-U4-LS3-V04","tier":"core"},{"word":"reason","pos":"noun","ipa":"/ˈrizən/","definition":"why you think something","arabic":"سبب (للرأي)","example":"Give a reason for your opinion.","image_id":"IMG-RW-L02-U4-LS3-V05","audio_id":"AUD-RW-L02-U4-LS3-V05","tier":"core"},{"word":"same","pos":"adjective","ipa":"/seɪm/","definition":"not different","arabic":"نفس / متشابه","example":"We wear the same uniform.","image_id":"IMG-RW-L02-U4-LS3-V06","audio_id":"AUD-RW-L02-U4-LS3-V06","tier":"core"},{"word":"boring","pos":"adjective","ipa":"/ˈbɔrɪŋ/","definition":"not fun or interesting","arabic":"ممل","example":"Some people say uniforms are boring.","image_id":"IMG-RW-L02-U4-LS3-V07","audio_id":"AUD-RW-L02-U4-LS3-V07","tier":"core"}],"explanation":{"text":"A **cause** is **why** something happens. An **effect** is **what happens**.\n\n**because** comes before the **cause**: *People wear raincoats **because** rain makes clothes wet.*\n\n**so** comes before the **effect**: *Rain makes clothes wet, **so** people wear raincoats.* Put a **comma** before so.","examples":["Cause: *Rain makes clothes wet.* → Effect: *People wear raincoats.*","**because**: People wear raincoats **because** rain makes clothes wet.","**so**: Rain makes clothes wet, **so** people wear raincoats.","Cause: *Their hands get very cold.* → Effect: *They wear gloves.* (main text)","Cause: *The sun is strong.* → Effect: *People wear hats.* (main text)","Sami: *I put on my uniform every morning, **so** I am never late.*","Sami: *We all wear the same clothes, **so** nobody feels left out.*","Opinion: *I think school uniforms are a good idea.* Reasons: easy, same clothes, one team.","Your turn: *It is cold, so ___.* → *It is cold, so I put on my scarf.*"],"common_errors":["✗ Because rain. People wear raincoats. → ✓ People wear raincoats because rain makes clothes wet. (Join the cause and effect in **one** sentence.)","✗ It is cold so I put on my jacket. → ✓ It is cold, so I put on my jacket. (Put a **comma** before **so**.)","✗ I wear gloves so my hands are cold. → ✓ I wear gloves because my hands are cold. (Use **because** before the cause.)","✗ Because it is hot, so I wear a hat. → ✓ Because it is hot, I wear a hat. / It is hot, so I wear a hat. (Use **because** OR **so**, not both.)","✗ My opinion uniforms are good. → ✓ In my opinion, uniforms are good. (Say **In my opinion,** or **I think**.)","✗ Nobody feel left out. → ✓ Nobody feels left out. (Nobody → **feels**.)"],"arabic":"السبب (cause) هو لماذا يحدث الشيء، والنتيجة (effect) هي ما يحدث.\n\nbecause (لأن) تأتي قبل السبب: People wear raincoats because rain makes clothes wet.\n\nso (لذلك) تأتي قبل النتيجة، ونضع فاصلة قبلها: Rain makes clothes wet, so people wear raincoats.\n\nلا نستخدم because وso معًا في الجملة نفسها كما نقول في العربية «لأنّ… لذلك»."},"video":{"script":[{"time":"00:00–00:20","narration":"Why? Because! What happens? So! Let's learn cause and effect.","on_screen":"Cause → Effect","visual":"A domino pushes another domino; labels 'cause' and 'effect' pop up."},{"time":"00:20–00:55","narration":"Rain makes clothes wet, so people wear raincoats. People wear raincoats because rain makes clothes wet.","on_screen":"because + cause · so + effect","visual":"A rain cloud (cause) and a raincoat (effect) swap places as the sentences change."},{"time":"00:55–01:45","narration":"Uniforms Are a Good Idea, by Sami. I think school uniforms are a good idea…","on_screen":"(opinion text)","visual":"Sami at a small podium; each reason appears as a numbered card."},{"time":"01:45–02:20","narration":"Find the cause and effect: I put on my uniform every morning, SO I am never late!","on_screen":"Cause → so → Effect","visual":"A clock shows 7:00; Sami dresses fast and arrives smiling."},{"time":"02:20–02:50","narration":"Now finish this: It is cold, so… I put on my scarf!","on_screen":"Your turn!","visual":"Layla wraps a scarf; Saqr shivers and gets a tiny scarf too."}],"captions_ar":["لماذا؟ لأنّ! ماذا يحدث؟ لذلك! لنتعلم السبب والنتيجة.","المطر يبلل الملابس، لذلك يلبس الناس معاطف المطر.","«الزي الموحد فكرة جيدة» بقلم سامي…","أجد السبب والنتيجة: ألبس زيي كل صباح، لذلك لا أتأخر أبدًا!","أكمل: الجو بارد، لذلك… ألبس وشاحي!"],"voice":"Narrator: American English, warm female teacher, speed 0.85. Sami reads his opinion text proudly."},"texts":[{"type":"reading","title":"Uniforms Are a Good Idea","body":"by Sami\n\nI think school uniforms are a good idea. Here are my reasons.\n\nFirst, uniforms are easy. I put on my white shirt and gray pants every morning, so I am never late.\n\nSecond, we all wear the same clothes, so nobody feels left out.\n\nThird, uniforms make us one team. People see our uniforms and know we are from the same school.\n\nSome people say uniforms are boring. But we can still choose our own socks and shoes!\n\nThat is why I think uniforms are a good idea.","word_count":90,"audio_id":"AUD-RW-L02-U4-LS3-T1","id":"TXT-RW-L02-U4-LS3-1","genre":"opinion/argument","role":"paired","difficulty":"200L–350L","glossary":[{"word":"reasons","definition":"why you think something","arabic":"أسباب"},{"word":"left out","definition":"not part of the group","arabic":"مُستبعَد / وحيد"},{"word":"boring","definition":"not fun","arabic":"ممل"}]}],"activities":[{"id":"RW-L02-U4-LS3-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Read *Uniforms Are a Good Idea*. Choose the answer.","instructions_ar":"اقرأ النص واختر الإجابة.","items":[{"q":"Who wrote *Uniforms Are a Good Idea*?","answer":"Sami","explanation":"Text: by Sami.","explanation_ar":"سامي.","options":["Layla","Sami","Mr. Khalid","Omar"],"dok":1,"skill":"author","text_id":"TXT-RW-L02-U4-LS3-1","stage":"controlled"},{"q":"What is Sami's opinion?","answer":"School uniforms are a good idea.","explanation":"First sentence.","explanation_ar":"الزي الموحد فكرة جيدة.","options":["School uniforms are a good idea.","Uniforms are boring.","Shoes are expensive.","Socks are the same."],"dok":1,"skill":"opinion","stage":"controlled"},{"q":"What color is Sami's school shirt?","answer":"white","explanation":"Text: my white shirt.","explanation_ar":"أبيض.","options":["gray","blue","white","green"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"How many reasons does Sami give?","answer":"three","explanation":"First, Second, Third.","explanation_ar":"ثلاثة.","options":["one","two","five","three"],"dok":1,"skill":"reasons","stage":"controlled"},{"q":"What can students still choose, says Sami?","answer":"their own socks and shoes","explanation":"Text: socks and shoes.","explanation_ar":"الجوارب والأحذية.","options":["their own socks and shoes","their own shirts","their own pants","their own school"],"dok":1,"skill":"key details","stage":"controlled"},{"q":"What do *some people* say about uniforms?","answer":"They are boring.","explanation":"Text: Some people say uniforms are boring.","explanation_ar":"مملة.","options":["They are easy.","They make a team.","They are boring.","They are clean."],"dok":1,"skill":"key details","stage":"controlled"}]},{"id":"RW-L02-U4-LS3-A2","type":"mcq","stage":"guided","instructions":"Guided practice: Cause or effect? Choose.","instructions_ar":"سبب أم نتيجة؟ اختر.","items":[{"q":"*I put on my uniform every morning, so I am never late.* What is the EFFECT?","answer":"I am never late.","explanation":"The effect comes after so.","explanation_ar":"النتيجة بعد so.","options":["I put on my uniform.","every morning","I am never late.","my uniform"],"dok":1,"skill":"cause and effect","stage":"guided"},{"q":"*We all wear the same clothes, so nobody feels left out.* What is the CAUSE?","answer":"We all wear the same clothes.","explanation":"The cause comes before so.","explanation_ar":"السبب قبل so.","options":["Nobody feels left out.","left out","nobody","We all wear the same clothes."],"dok":1,"skill":"cause and effect","stage":"guided"},{"q":"*People wear raincoats because rain makes clothes wet.* What is the CAUSE?","answer":"Rain makes clothes wet.","explanation":"The cause comes after because.","explanation_ar":"السبب بعد because.","options":["People wear raincoats.","Rain makes clothes wet.","raincoats","people"],"dok":2,"skill":"cause and effect","stage":"guided"},{"q":"Which word comes before an EFFECT?","answer":"so","explanation":"so + effect.","explanation_ar":"so.","options":["because","and","but","so"],"dok":1,"skill":"signal words","stage":"guided"},{"q":"Finish the sentence: *It is very sunny, so ___.*","answer":"I wear a hat.","explanation":"Sun → hat.","explanation_ar":"ألبس قبعة.","options":["I wear gloves.","because it is hot.","I wear a hat.","it rains."],"dok":2,"skill":"cause and effect","stage":"guided"},{"q":"Finish the sentence: *Omar takes off his jacket because ___.*","answer":"the classroom is warm","explanation":"A reason to take it off.","explanation_ar":"الفصل دافئ.","options":["the classroom is warm","it is snowing","his jacket is new","he is cold"],"dok":2,"skill":"cause and effect","stage":"guided"}]},{"id":"RW-L02-U4-LS3-A3","type":"organizer","stage":"freer","instructions":"Organizer: Complete the Cause → Effect Chain.","instructions_ar":"أكمل سلسلة السبب والنتيجة.","items":[{"q":"Cause: Their hands get very cold. Effect: ___","answer":"They wear gloves.","explanation":"Main text, Cold places.","explanation_ar":"من النص الرئيسي.","dok":1,"skill":"cause and effect","stage":"freer"},{"q":"Cause: ___ Effect: People wear hats.","answer":"The sun is strong. / The sun can burn their heads.","explanation":"Main text, Hot places.","explanation_ar":"من النص الرئيسي.","dok":2,"skill":"cause and effect","stage":"freer"},{"q":"Cause: People see our uniforms. Effect: ___","answer":"They know we are from the same school.","explanation":"Sami's third reason.","explanation_ar":"السبب الثالث لسامي.","dok":2,"skill":"cause and effect","stage":"freer"},{"q":"Write your own chain: cause → so → effect → so → next effect.","answer":"It is cold. → so → I put on my scarf. → so → my neck is warm.","explanation":"Two arrows.","explanation_ar":"سهمان.","dok":3,"skill":"cause and effect","stage":"freer"}]},{"id":"RW-L02-U4-LS3-A4","type":"open","stage":"production","instructions":"Writing: Write with because and so.","instructions_ar":"اكتب بـ because وso.","items":[{"q":"Join with so: *My shirt is dirty.* + *I put on a clean shirt.*","answer":"My shirt is dirty, so I put on a clean shirt.","explanation":"Comma + so.","explanation_ar":"فاصلة + so.","dok":2,"skill":"joining sentences","stage":"production"},{"q":"Join with because: *I fold my clothes.* + *My room looks neat.*","answer":"I fold my clothes because I want my room to look neat.","explanation":"because + reason.","explanation_ar":"because + سبب.","dok":2,"skill":"joining sentences","stage":"production"},{"q":"Do you agree with Sami? Write your opinion and one reason with because.","answer":"I agree with Sami because uniforms are easy in the morning.","explanation":"Opinion + because.","explanation_ar":"رأي + because.","dok":3,"skill":"opinion","stage":"production"},{"q":"Write one more reason that uniforms are a good idea. Use so.","answer":"Uniforms are strong, so they last a long time.","explanation":"Reason with so.","explanation_ar":"سبب بـ so.","dok":3,"skill":"reasons","stage":"production"}]},{"id":"RW-L02-U4-LS3-TR-1","type":"timed_reading","instructions":"Timed reading: Read \"Uniforms Are a Good Idea\" aloud or silently. Try to finish in the time.","instructions_ar":"اقرأ النص وحاول أن تنهيه في الوقت المحدد.","items":[{"q":"Read “Uniforms Are a Good Idea”.","answer":"90 words","title":"Uniforms Are a Good Idea","body":"by Sami\n\nI think school uniforms are a good idea. Here are my reasons.\n\nFirst, uniforms are easy. I put on my white shirt and gray pants every morning, so I am never late.\n\nSecond, we all wear the same clothes, so nobody feels left out.\n\nThird, uniforms make us one team. People see our uniforms and know we are from the same school.\n\nSome people say uniforms are boring. But we can still choose our own socks and shoes!\n\nThat is why I think uniforms are a good idea.","words":90,"limit":113}],"time_limit_sec":113},{"id":"RW-L02-U4-LS3-ORG","type":"organizer","organizer":"Cause → Effect Chain","instructions":"Organizer: Write the cause in the first box and the effect in the next box. Add because or so on the arrow.","items":[{"q":"Cause","answer":"It is very cold in Canada."},{"q":"→ so →","answer":"so"},{"q":"Effect","answer":"People put on wool jackets and gloves."},{"q":"→ so →","answer":"so"},{"q":"Next effect","answer":"They stay warm outside."}]}],"game":{"name":"Domino Chains","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Domino tap: the child taps the domino whose cause matches the last effect; the chain falls when it is complete, and the child reads it with so.","Teams of four share a set of domino cards.","Start with the card 'It is very cold.'","Players take turns adding a card whose cause follows from the last effect.","Each player reads the link aloud with so.","The longest correct chain in 3 minutes wins."],"data":[]},"exit_quiz":[{"q":"A cause is ___.","answer":"why something happens","explanation":"Cause = why.","explanation_ar":"لماذا يحدث.","options":["what happens","the title","a question","why something happens"],"dok":1,"skill":"cause and effect"},{"q":"An effect is ___.","answer":"what happens","explanation":"Effect = what happens.","explanation_ar":"ما يحدث.","options":["what happens","why it happens","the writer's name","a heading"],"dok":1,"skill":"cause and effect"},{"q":"Which word comes before a cause?","answer":"because","explanation":"because + cause.","explanation_ar":"because.","options":["because","so","then","first"],"dok":1,"skill":"signal words"},{"q":"Which sentence with *so* about the snow has the comma in the right place?","answer":"It is snowing, so I wear boots.","explanation":"Comma before so.","explanation_ar":"الفاصلة قبل so.","options":["It is snowing so, I wear boots.","It is, snowing so I wear boots.","It is snowing, so I wear boots.","It is snowing so I, wear boots."],"dok":1,"skill":"punctuation"},{"q":"*In my opinion, uniforms are good.* *Opinion* means ___.","answer":"what you think","explanation":"Opinion = what you think.","explanation_ar":"رأي.","options":["a fact you can count","what you think","a kind of shirt","a school rule"],"dok":1,"skill":"vocabulary"},{"q":"Which is a REASON Sami gives?","answer":"Uniforms make us one team.","explanation":"Third reason.","explanation_ar":"سبب من أسبابه.","options":["Uniforms are boring.","Shoes are expensive.","Uniforms are new.","Uniforms make us one team."],"dok":2,"skill":"reasons"},{"q":"Which sentence about a sun hat uses *because* correctly?","answer":"I wear a hat because the sun is strong.","explanation":"because + cause.","explanation_ar":"استخدام صحيح.","options":["I wear a hat because.","Because I wear a hat, so the sun is strong.","I wear a hat because the sun is strong.","The sun is strong because I wear a hat."],"dok":2,"skill":"cause and effect"},{"q":"Why does Sami write *But we can still choose our own socks and shoes!*?","answer":"to answer people who say uniforms are boring","explanation":"He answers the other side.","explanation_ar":"ليرد على من يقول إنها مملة.","options":["to answer people who say uniforms are boring","to say uniforms are bad","to give the title","to tell a story"],"dok":3,"skill":"author's purpose"},{"q":"How is *Clothes for Hot and Cold Places* different from Sami's text?","answer":"The first gives facts; Sami's text gives an opinion.","explanation":"Facts vs. opinion.","explanation_ar":"حقائق مقابل رأي.","options":["Both are stories.","The first gives an opinion; Sami's gives facts.","Both are poems.","The first gives facts; Sami's text gives an opinion."],"dok":3,"skill":"compare texts"},{"q":"*Nobody feels left out.* Which word means *left out*?","answer":"not part of the group","explanation":"Left out = not included.","explanation_ar":"غير مشمول.","options":["very late","not part of the group","outside the school","very cold"],"dok":2,"skill":"word in context"}],"images":[{"id":"IMG-RW-L02-U4-LS3-V01","prompt":"Picture for the word 'cause': a cloud raining (cause) with an arrow"},{"id":"IMG-RW-L02-U4-LS3-V02","prompt":"Picture for the word 'effect': wet clothes after the arrow"},{"id":"IMG-RW-L02-U4-LS3-V03","prompt":"Picture for the word 'so': a thermometer arrow pointing to a jacket"},{"id":"IMG-RW-L02-U4-LS3-V04","prompt":"Picture for the word 'opinion': a child with a thought bubble and a thumbs-up"},{"id":"IMG-RW-L02-U4-LS3-V05","prompt":"Picture for the word 'reason': a child counting reasons on fingers"},{"id":"IMG-RW-L02-U4-LS3-V06","prompt":"Picture for the word 'same': three identical shirts in a row"},{"id":"IMG-RW-L02-U4-LS3-V07","prompt":"Picture for the word 'boring': a child yawning"},{"id":"IMG-RW-L02-U4-LS3-01","prompt":"Sami holds his opinion text while classmates in uniforms wave."},{"id":"IMG-RW-L02-U4-LS3-02","prompt":"Boxes and arrows for a cause-and-effect chain."},{"id":"IMG-RW-L02-U4-LS3-03","prompt":"Dominoes falling from cause to effect."}],"audio":[{"id":"AUD-RW-L02-U4-LS3-V01","script":"cause. The rain is the cause. Our clothes are wet."},{"id":"AUD-RW-L02-U4-LS3-V02","script":"effect. Wet clothes are the effect of the rain."},{"id":"AUD-RW-L02-U4-LS3-V03","script":"so. It is cold, so I put on my jacket."},{"id":"AUD-RW-L02-U4-LS3-V04","script":"opinion. In my opinion, uniforms are good."},{"id":"AUD-RW-L02-U4-LS3-V05","script":"reason. Give a reason for your opinion."},{"id":"AUD-RW-L02-U4-LS3-V06","script":"same. We wear the same uniform."},{"id":"AUD-RW-L02-U4-LS3-V07","script":"boring. Some people say uniforms are boring."},{"id":"AUD-RW-L02-U4-LS3-T1","script":"by Sami I think school uniforms are a good idea. Here are my reasons. First, uniforms are easy. I put on my white shirt and gray pants every morning, so I am never late. Second, we all wear the same clothes, so nobody feels left out. Third, uniforms make us one team. People see our uniforms and know we are from the same school. Some people say uniforms are boring. But we can still choose our own socks and shoes! That is why I think uniforms are a good idea."},{"id":"AUD-RW-L02-U4-LS3-VID","script":"Why? Because! What happens? So! Let's learn cause and effect. Rain makes clothes wet, so people wear raincoats. People wear raincoats because rain makes clothes wet. Uniforms Are a Good Idea, by Sami. I think school uniforms are a good idea… Find the cause and effect: I put on my uniform every morning, SO I am never late! Now finish this: It is cold, so… I put on my scarf!"}]},{"id":"RW-L02-U4-LS4","title":"Writing Skill: Describing words before nouns","lesson_type":"writing_skill","objectives":["put describing words before nouns (a blue scarf, my warm jacket)","use size, color and material words in the order size → color → material","make a plain sentence more interesting by adding describing words"],"objectives_ar":["وضع الصفات قبل الأسماء.","استخدام صفات الحجم واللون والمادة بالترتيب: حجم ← لون ← مادة.","جعل الجملة البسيطة أكثر تشويقًا بإضافة الصفات."],"success_criteria":["I can put a describing word before a noun.","I can use size, color and material in the right order.","I can add describing words to a plain sentence."],"success_criteria_ar":["أستطيع وضع الصفة قبل الاسم.","أستطيع استخدام الحجم واللون والمادة بالترتيب الصحيح.","أستطيع إضافة صفات إلى جملة بسيطة."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"describing word","pos":"noun","ipa":"/dɪˈskraɪbɪŋ wɝd/","definition":"a word that tells what a noun is like (an adjective)","arabic":"صفة","example":"*Blue* is a describing word.","image_id":"IMG-RW-L02-U4-LS4-V01","audio_id":"AUD-RW-L02-U4-LS4-V01","tier":"core"},{"word":"noun","pos":"noun","ipa":"/naʊn/","definition":"a word for a person, place or thing","arabic":"اسم","example":"*Scarf* is a noun.","image_id":"IMG-RW-L02-U4-LS4-V02","audio_id":"AUD-RW-L02-U4-LS4-V02","tier":"core"},{"word":"soft","pos":"adjective","ipa":"/sɔft/","definition":"nice and smooth to touch; not hard","arabic":"ناعم / طري","example":"My scarf is soft.","image_id":"IMG-RW-L02-U4-LS4-V03","audio_id":"AUD-RW-L02-U4-LS4-V03","tier":"core"},{"word":"wooden","pos":"adjective","ipa":"/ˈwʊdən/","definition":"made of wood","arabic":"خشبي","example":"I keep my scarf in a wooden box.","image_id":"IMG-RW-L02-U4-LS4-V04","audio_id":"AUD-RW-L02-U4-LS4-V04","tier":"core"},{"word":"favorite","pos":"adjective","ipa":"/ˈfeɪvərɪt/","definition":"the one you like the most","arabic":"المفضّل","example":"Blue is my favorite color.","image_id":"IMG-RW-L02-U4-LS4-V05","audio_id":"AUD-RW-L02-U4-LS4-V05","tier":"core"},{"word":"grandmother","pos":"noun","ipa":"/ˈɡrænmʌðər/","definition":"the mother of your mother or father","arabic":"جدة","example":"My grandmother made my scarf.","image_id":"IMG-RW-L02-U4-LS4-V06","audio_id":"AUD-RW-L02-U4-LS4-V06","tier":"core"},{"word":"winter","pos":"noun","ipa":"/ˈwɪntər/","definition":"the coldest season of the year","arabic":"الشتاء","example":"Taif is cool in winter.","image_id":"IMG-RW-L02-U4-LS4-V07","audio_id":"AUD-RW-L02-U4-LS4-V07","tier":"core"}],"explanation":{"text":"A **describing word** (an adjective) tells us more about a **noun**. In English, it comes **before** the noun: *a **blue** scarf*.\n\nWith two or three describing words, use this order: **size → color → material → noun**: *a **small white cotton** shirt*.\n\nDescribing words make writing **more interesting**: *I have a scarf.* → *I have a **long, soft** scarf.*","examples":["**a blue scarf** – color + noun.","**a long scarf** – size + noun.","**a wool scarf** – material + noun.","**a long blue scarf** – size + color + noun.","**a blue wool scarf** – color + material + noun.","**a big brown leather bag** – size + color + material + noun.","**my new black shoes** – my + describing words + noun.","Plain: *I wear a jacket.* → Better: *I wear a **thick gray** jacket.*","Plain: *Grandpa has a thobe.* → Better: *Grandpa has a **long white cotton** thobe.*"],"common_errors":["✗ a scarf blue → ✓ a blue scarf (Describing word **before** the noun.)","✗ a wool blue scarf → ✓ a blue wool scarf (Color comes **before** material.)","✗ whites stars → ✓ white stars (Describing words have **no -s**.)","✗ my shoes new → ✓ my new shoes (After **my**, put the describing word before the noun.)","✗ a old jacket → ✓ an old jacket (Use **an** before a vowel sound (a, e, i, o, u).)","✗ The jacket is gray thick. → ✓ The jacket is thick and gray. (After *is*, join two describing words with **and**.)"],"arabic":"الصفة (describing word) تخبرنا أكثر عن الاسم، وفي الإنجليزية تأتي قبل الاسم: a blue scarf، بعكس العربية «وشاح أزرق».\n\nعند استخدام أكثر من صفة نرتبها: الحجم ← اللون ← المادة ← الاسم: a small white cotton shirt.\n\nالصفات لا تُجمع ولا تتغير مع الاسم الجمع: white stars وليس whites stars.\n\nالصفات تجعل الكتابة أكثر تشويقًا: I have a scarf ← I have a long, soft scarf."},"video":{"script":[{"time":"00:00–00:15","narration":"Layla loves her scarf! Let's read her description.","on_screen":"My Favorite Scarf","visual":"Layla wraps a blue scarf with white stars; mist over Taif mountains."},{"time":"00:15–00:55","narration":"I have a long, soft scarf. It is a blue wool scarf with small white stars…","on_screen":"(model text)","visual":"Each describing word glows coral as Layla reads."},{"time":"00:55–01:35","narration":"Where does the describing word go? BEFORE the noun: a blue scarf!","on_screen":"describing word → noun","visual":"The word 'blue' hops in front of 'scarf'; 'scarf blue' gets a red cross."},{"time":"01:35–02:10","narration":"Size, color, material: a small white cotton shirt!","on_screen":"size → color → material → noun","visual":"Three train cars (size, color, material) pull the noun car."},{"time":"02:10–02:40","narration":"Make it interesting: I wear a jacket… I wear a thick gray jacket!","on_screen":"Plain → Better!","visual":"A plain gray outline of a jacket fills with color and texture."}],"captions_ar":["ليلى تحب وشاحها! لنقرأ وصفها.","عندي وشاح طويل ناعم، وهو وشاح صوفي أزرق عليه نجوم بيضاء صغيرة…","أين تأتي الصفة؟ قبل الاسم: a blue scarf!","الحجم ثم اللون ثم المادة: a small white cotton shirt!","اجعلها مشوقة: I wear a jacket ← I wear a thick gray jacket!"],"voice":"Narrator: American English, warm female teacher, speed 0.85. Layla reads her description softly and proudly."},"texts":[{"type":"model","title":"My Favorite Scarf (by Layla)","body":"I have a long, soft scarf. It is a blue wool scarf with small white stars. My grandmother made it for me.\n\nI wear my warm scarf on cold winter mornings in Taif. I put it on with my thick gray jacket.\n\nAt home, I fold it and put it in a big wooden box. It is my favorite scarf!","word_count":60,"audio_id":"AUD-RW-L02-U4-LS4-T1","id":"TXT-RW-L02-U4-LS4-1","genre":"model text","role":"model","difficulty":"200L–350L","glossary":[],"annotations":["**a long, soft scarf** – two describing words **before** the noun *scarf*. Use a comma between them.","**a blue wool scarf** – color (blue) + material (wool) + noun.","**small white stars** – size (small) + color (white) + noun. No **-s** on *small* or *white*.","**my warm scarf** – after *my*, the describing word still comes **before** the noun.","**a big wooden box** – size (big) + material (wooden) + noun.","**It is my favorite scarf!** – a strong feeling at the end ends with an **exclamation mark**."]}],"activities":[{"id":"RW-L02-U4-LS4-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the correct phrase.","instructions_ar":"اختر العبارة الصحيحة.","items":[{"q":"Which phrase about Layla's scarf puts the color first and the material second?","answer":"a blue wool scarf","explanation":"Color before material.","explanation_ar":"اللون قبل المادة.","options":["a wool blue scarf","a scarf blue wool","a blue wool scarf","blue a wool scarf"],"dok":1,"skill":"adjective order","stage":"controlled"},{"q":"Which phrase about a cotton shirt is in the right order?","answer":"a small white cotton shirt","explanation":"Size → color → material.","explanation_ar":"حجم ← لون ← مادة.","options":["a cotton white small shirt","a white small cotton shirt","a small white cotton shirt","a shirt small white cotton"],"dok":2,"skill":"adjective order","stage":"controlled"},{"q":"Which phrase about stars is correct?","answer":"small white stars","explanation":"No -s on describing words.","explanation_ar":"دون s.","options":["smalls whites stars","small white stars","stars small white","small whites stars"],"dok":1,"skill":"no plural adjectives","stage":"controlled"},{"q":"Which phrase about a jacket is correct?","answer":"an old jacket","explanation":"an before a vowel sound.","explanation_ar":"an قبل حرف العلة.","options":["an old jacket","a old jacket","old a jacket","an jacket old"],"dok":2,"skill":"articles","stage":"controlled"},{"q":"In *a big wooden box*, which word is the noun?","answer":"box","explanation":"Box is the thing.","explanation_ar":"box.","options":["big","box","wooden","a"],"dok":1,"skill":"nouns","stage":"controlled"},{"q":"In *my thick gray jacket*, which words are describing words?","answer":"thick, gray","explanation":"They tell what the jacket is like.","explanation_ar":"thick وgray.","options":["my, jacket","jacket, gray","my, thick","thick, gray"],"dok":1,"skill":"describing words","stage":"controlled"}]},{"id":"RW-L02-U4-LS4-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the words in order.","instructions_ar":"رتّب الكلمات.","items":[{"q":"Build a phrase about Grandpa's thobe.","answer":"a long white thobe","explanation":"Size → color → noun.","explanation_ar":"حجم ← لون ← اسم.","stage":"guided","parts":["a","thobe","white","long"],"target":["a","long","white","thobe"]},{"q":"Build a phrase about Omar's shoes.","answer":"my new black shoes","explanation":"my + describing words + noun.","explanation_ar":"my + صفات + اسم.","stage":"guided","parts":["new","shoes","black","my"],"target":["my","new","black","shoes"]},{"q":"Build a phrase about Mr. Khalid's bag.","answer":"a big brown leather bag","explanation":"Size → color → material → noun.","explanation_ar":"حجم ← لون ← مادة ← اسم.","stage":"guided","parts":["a","big","leather","bag","brown"],"target":["a","big","brown","leather","bag"]},{"q":"Build a sentence about a winter jacket.","answer":"I wear a thick gray jacket.","explanation":"Subject + verb + a + describing words + noun.","explanation_ar":"فاعل + فعل + صفات + اسم.","stage":"guided","parts":["I","jacket.","gray","wear","a","thick"],"target":["I","wear","a","thick","gray","jacket."]},{"q":"Build a sentence about Lama's socks.","answer":"Lama has small pink socks.","explanation":"Size → color → noun.","explanation_ar":"حجم ← لون ← اسم.","stage":"guided","parts":["small","socks.","has","Lama","pink"],"target":["Lama","has","small","pink","socks."]},{"q":"Build a sentence about Faris's shirt.","answer":"Faris wears a green cotton shirt.","explanation":"Color → material → noun.","explanation_ar":"لون ← مادة ← اسم.","stage":"guided","parts":["shirt.","cotton","green","wears","Faris","a"],"target":["Faris","wears","a","green","cotton","shirt."]}]},{"id":"RW-L02-U4-LS4-A3","type":"gap_fill","stage":"freer","instructions":"Freer practice: Add a describing word from the word bank.","instructions_ar":"أضف صفة من بنك الكلمات.","items":[{"q":"My grandmother made a ________ scarf for me. It is nice to touch.","answer":"soft","explanation":"Nice to touch = soft.","explanation_ar":"ناعم.","stage":"freer"},{"q":"I keep my toys in a ________ box made of wood.","answer":"wooden","explanation":"Made of wood.","explanation_ar":"خشبي.","stage":"freer"},{"q":"Blue is my ________ color. I like it the most.","answer":"favorite","explanation":"The one you like most.","explanation_ar":"المفضّل.","stage":"freer"},{"q":"In ________, I wear a warm jacket in Taif.","answer":"winter","explanation":"The coldest season.","explanation_ar":"الشتاء.","stage":"freer"},{"q":"Grandpa wears a ________ white thobe. It goes down to his feet.","answer":"long","explanation":"Down to his feet = long.","explanation_ar":"طويل.","stage":"freer"},{"q":"These are ________ shoes. They are made of leather.","answer":"leather","explanation":"Material word.","explanation_ar":"جلدية.","stage":"freer"}]},{"id":"RW-L02-U4-LS4-A4","type":"open","stage":"production","instructions":"Writing: Make it more interesting.","instructions_ar":"اجعلها أكثر تشويقًا.","items":[{"q":"Add two describing words: *I have a hat.*","answer":"I have a big straw hat.","explanation":"Two describing words before hat.","explanation_ar":"صفتان قبل hat.","dok":1,"skill":"adding adjectives","stage":"production"},{"q":"Add two describing words: *Noura wears shoes.*","answer":"Noura wears new black shoes.","explanation":"No -s on describing words.","explanation_ar":"دون s.","dok":2,"skill":"adding adjectives","stage":"production"},{"q":"Fix the order: *Omar has a jacket green sports.*","answer":"Omar has a green sports jacket.","explanation":"Describing words before the noun.","explanation_ar":"الصفات قبل الاسم.","dok":2,"skill":"editing","stage":"production"},{"q":"Describe your school bag in two sentences. Use size, color and material.","answer":"I have a big blue school bag. It has a small black plastic bottle in it.","explanation":"Size + color + material.","explanation_ar":"حجم + لون + مادة.","dok":3,"skill":"describing","stage":"production"}]}],"game":{"name":"Describing Train","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Train builder: train cars labelled with words drop on the track; the child connects them in the order size → color → material → noun. A correct train whistles and drives away.","Teams get a pile of mixed cards face down.","Each player takes a card and adds it to the team train in the right place.","Teams read their phrase aloud: 'a small white cotton shirt'.","A correct phrase = 1 point per describing word.","Wrong order? Another team can fix it and steal the points."],"data":[]},"exit_quiz":[{"q":"In English, where does a describing word usually go?","answer":"before the noun","explanation":"Describing word + noun.","explanation_ar":"قبل الاسم.","options":["before the noun","after the noun","at the end of the sentence","after the period"],"dok":1,"skill":"word order"},{"q":"Which word is a noun?","answer":"jacket","explanation":"A jacket is a thing.","explanation_ar":"اسم.","options":["thick","jacket","gray","soft"],"dok":1,"skill":"nouns"},{"q":"Which phrase about Grandpa's shemagh is correct?","answer":"a red and white shemagh","explanation":"Describing words before the noun.","explanation_ar":"الصفات قبل الاسم.","options":["a shemagh red and white","shemagh a red white","a reds whites shemagh","a red and white shemagh"],"dok":1,"skill":"word order"},{"q":"*My grandmother made a soft scarf.* *Soft* means ___.","answer":"nice and smooth to touch","explanation":"Soft = smooth to touch.","explanation_ar":"ناعم.","options":["very hard","very long","nice and smooth to touch","made of wood"],"dok":1,"skill":"vocabulary"},{"q":"Which order is correct for describing words?","answer":"size → color → material","explanation":"Size, color, material.","explanation_ar":"حجم ← لون ← مادة.","options":["size → color → material","material → size → color","color → size → material","material → color → size"],"dok":2,"skill":"adjective order"},{"q":"Which phrase about a wooden box is in the right order?","answer":"a big brown wooden box","explanation":"Size → color → material.","explanation_ar":"ترتيب صحيح.","options":["a wooden brown big box","a big brown wooden box","a brown big wooden box","a big wooden brown box"],"dok":2,"skill":"adjective order"},{"q":"Fix it: *a old scarf*","answer":"an old scarf","explanation":"an before a vowel sound.","explanation_ar":"an.","options":["a olds scarf","an scarf old","old a scarf","an old scarf"],"dok":2,"skill":"articles"},{"q":"Which sentence is the MOST interesting?","answer":"I wear a long, soft blue scarf.","explanation":"More describing words.","explanation_ar":"فيه صفات أكثر.","options":["I wear a scarf.","I wear it.","Scarf.","I wear a long, soft blue scarf."],"dok":2,"skill":"word choice"},{"q":"Why does Layla write *a long, soft scarf* and not just *a scarf*?","answer":"to help the reader picture her scarf","explanation":"Describing words make a picture.","explanation_ar":"ليتخيل القارئ وشاحها.","options":["to make the text shorter","to say where the scarf is","to help the reader picture her scarf","to ask a question"],"dok":3,"skill":"author's craft"},{"q":"Which describing word tells the MATERIAL of a box?","answer":"wooden","explanation":"Wooden = made of wood.","explanation_ar":"خشبي.","options":["big","wooden","brown","favorite"],"dok":1,"skill":"describing words"}],"images":[{"id":"IMG-RW-L02-U4-LS4-V01","prompt":"Picture for the word 'describing word': a word card 'blue' pointing to a scarf"},{"id":"IMG-RW-L02-U4-LS4-V02","prompt":"Picture for the word 'noun': picture cards of a girl, a school and a scarf"},{"id":"IMG-RW-L02-U4-LS4-V03","prompt":"Picture for the word 'soft': a hand touching a fluffy scarf"},{"id":"IMG-RW-L02-U4-LS4-V04","prompt":"Picture for the word 'wooden': a wooden box with a lid"},{"id":"IMG-RW-L02-U4-LS4-V05","prompt":"Picture for the word 'favorite': a child hugging a scarf with a heart"},{"id":"IMG-RW-L02-U4-LS4-V06","prompt":"Picture for the word 'grandmother': a smiling grandmother knitting"},{"id":"IMG-RW-L02-U4-LS4-V07","prompt":"Picture for the word 'winter': a cool morning with mist over the mountains"},{"id":"IMG-RW-L02-U4-LS4-01","prompt":"Layla wears her blue scarf with white stars on a misty morning."},{"id":"IMG-RW-L02-U4-LS4-02","prompt":"A toy train showing the order size, color, material, noun."},{"id":"IMG-RW-L02-U4-LS4-03","prompt":"A plain jacket outline and a colorful detailed jacket."}],"audio":[{"id":"AUD-RW-L02-U4-LS4-V01","script":"describing word. *Blue* is a describing word."},{"id":"AUD-RW-L02-U4-LS4-V02","script":"noun. *Scarf* is a noun."},{"id":"AUD-RW-L02-U4-LS4-V03","script":"soft. My scarf is soft."},{"id":"AUD-RW-L02-U4-LS4-V04","script":"wooden. I keep my scarf in a wooden box."},{"id":"AUD-RW-L02-U4-LS4-V05","script":"favorite. Blue is my favorite color."},{"id":"AUD-RW-L02-U4-LS4-V06","script":"grandmother. My grandmother made my scarf."},{"id":"AUD-RW-L02-U4-LS4-V07","script":"winter. Taif is cool in winter."},{"id":"AUD-RW-L02-U4-LS4-T1","script":"I have a long, soft scarf. It is a blue wool scarf with small white stars. My grandmother made it for me. I wear my warm scarf on cold winter mornings in Taif. I put it on with my thick gray jacket. At home, I fold it and put it in a big wooden box. It is my favorite scarf!"},{"id":"AUD-RW-L02-U4-LS4-VID","script":"Layla loves her scarf! Let's read her description. I have a long, soft scarf. It is a blue wool scarf with small white stars… Where does the describing word go? BEFORE the noun: a blue scarf! Size, color, material: a small white cotton shirt! Make it interesting: I wear a jacket… I wear a thick gray jacket!"}]},{"id":"RW-L02-U4-LS5","title":"Writing Workshop: What I Wear on Eid","lesson_type":"writing_workshop","objectives":["plan a description of Eid clothes with a Hamburger Plan: topic sentence, details, closing","write 6 describing sentences with describing words before nouns and one because or so sentence","revise to add describing words, edit and publish the description with a drawing"],"objectives_ar":["التخطيط لوصف ملابس العيد بخطة الهامبرغر: جملة موضوع وتفاصيل وخاتمة.","كتابة 6 جمل وصفية بصفات قبل الأسماء وجملة واحدة بـ because أو so.","التحسين بإضافة صفات، ثم التدقيق والنشر مع رسم."],"success_criteria":["I can plan a topic sentence, details and a closing.","I can describe my clothes with size, color and material.","I can check capitals, periods and word order."],"success_criteria_ar":["أستطيع التخطيط لجملة موضوع وتفاصيل وخاتمة.","أستطيع وصف ملابسي بالحجم واللون والمادة.","أستطيع مراجعة الحروف الكبيرة والنقاط وترتيب الكلمات."],"map_area":"Language Usage: Write, Revise Texts for Purpose and Audience (cross-strand)","vocabulary":[{"word":"Eid","pos":"noun","ipa":"/id/","definition":"a happy Muslim holiday (Eid al-Fitr, Eid al-Adha)","arabic":"العيد","example":"We wear new clothes on Eid.","image_id":"IMG-RW-L02-U4-LS5-V01","audio_id":"AUD-RW-L02-U4-LS5-V01","tier":"core"},{"word":"new","pos":"adjective","ipa":"/nu/","definition":"not old; just bought or made","arabic":"جديد","example":"I have new shoes for Eid.","image_id":"IMG-RW-L02-U4-LS5-V02","audio_id":"AUD-RW-L02-U4-LS5-V02","tier":"core"},{"word":"shiny","pos":"adjective","ipa":"/ˈʃaɪni/","definition":"bright, with light on it","arabic":"لامع","example":"My shoes are shiny.","image_id":"IMG-RW-L02-U4-LS5-V03","audio_id":"AUD-RW-L02-U4-LS5-V03","tier":"core"},{"word":"smart","pos":"adjective","ipa":"/smɑrt/","definition":"neat and nice-looking (for clothes)","arabic":"أنيق","example":"You look smart in your thobe!","image_id":"IMG-RW-L02-U4-LS5-V04","audio_id":"AUD-RW-L02-U4-LS5-V04","tier":"core"},{"word":"topic sentence","pos":"noun","ipa":"/ˈtɑpɪk ˈsɛntəns/","definition":"the first sentence that tells what the writing is about","arabic":"الجملة الرئيسية (جملة الموضوع)","example":"My topic sentence is: On Eid, I wear my new clothes.","image_id":"IMG-RW-L02-U4-LS5-V05","audio_id":"AUD-RW-L02-U4-LS5-V05","tier":"core"},{"word":"detail","pos":"noun","ipa":"/ˈditeɪl/","definition":"a small piece of information","arabic":"تفصيل","example":"Add a detail about your shoes.","image_id":"IMG-RW-L02-U4-LS5-V06","audio_id":"AUD-RW-L02-U4-LS5-V06","tier":"core"},{"word":"closing","pos":"noun","ipa":"/ˈkloʊzɪŋ/","definition":"the last sentence that ends the writing","arabic":"الجملة الختامية","example":"My closing is: I love Eid!","image_id":"IMG-RW-L02-U4-LS5-V07","audio_id":"AUD-RW-L02-U4-LS5-V07","tier":"core"}],"explanation":{"text":"A **description** helps the reader **see** something in their mind.\n\nUse the **Hamburger Plan**: the **top bun** is the **topic sentence**; the **layers** are **details** (one for each clothes item); the **bottom bun** is the **closing** – a feeling sentence.\n\nIn each detail, put **describing words before the noun** (size → color → material) and add one sentence with **because** or **so**.","examples":["Topic sentence: **On Eid, I wear my new clothes.**","Detail 1: **I wear a long white thobe.**","Detail 2: **I put on a red and white shemagh.**","Detail 3: **I have shiny black leather shoes.**","Detail 4: **I wear soft white socks because my new shoes are hard.**","Detail 5: **My father gives me a small blue box, so I am excited!**","Closing: **I look smart in my Eid clothes, and I feel very happy!**","A girl's details: **I wear a long green dress with small gold flowers. I have new pink shoes.**","A baby's details: **Dana wears a tiny yellow dress and white socks.**"],"common_errors":["✗ I wear thobe white new. → ✓ I wear a new white thobe. (Use **a** and put describing words before the noun.)","✗ on eid i wear my new clothes → ✓ On Eid, I wear my new clothes. (Capitals for **On**, **Eid** and **I**; end with a period.)","✗ I have shoes shiny. → ✓ I have shiny shoes. (Describing word first.)","✗ My shoes is new. → ✓ My shoes are new. (Shoes → **are**.)","✗ I wear socks because. → ✓ I wear socks because my shoes are hard. (Finish the reason after **because**.)","✗ (No closing sentence) → ✓ I love my Eid clothes! (End with a **closing** feeling sentence.)"],"arabic":"الوصف يساعد القارئ على أن يرى الشيء في خياله.\n\nخطة الهامبرغر: الخبزة العليا هي جملة الموضوع، والطبقات هي التفاصيل (تفصيل لكل قطعة ملابس)، والخبزة السفلى هي الخاتمة (جملة شعور).\n\nفي كل تفصيل ضع الصفات قبل الاسم (الحجم ← اللون ← المادة)، وأضف جملة واحدة بـ because أو so.\n\nتذكّر: كلمة Eid تبدأ دائمًا بحرف كبير."},"video":{"script":[{"time":"00:00–00:15","narration":"Eid Mubarak! Omar wants to describe his Eid clothes.","on_screen":"What I Wear on Eid","visual":"Omar in front of a mirror on Eid morning; a decorated door behind him."},{"time":"00:15–00:50","narration":"Plan with a hamburger! Top bun: topic sentence. Layers: details. Bottom bun: closing.","on_screen":"1 Plan – Hamburger 🍔","visual":"A burger builds layer by layer with labels."},{"time":"00:50–01:40","narration":"Draft: On Eid, I wear my new clothes. I wear a long white thobe. I have shiny black leather shoes…","on_screen":"2 Draft – describing words before nouns","visual":"Each clothes item appears on Omar as the sentence is read."},{"time":"01:40–02:05","narration":"Revise: add a describing word! I wear socks… I wear SOFT WHITE socks because my new shoes are hard.","on_screen":"3 Revise ➕ describing words","visual":"Two new coral words pop into the sentence."},{"time":"02:05–02:30","narration":"Edit: capital E for Eid, capital I, periods – check! Describing words before nouns – check!","on_screen":"4 Edit E · I · .","visual":"Capitals grow; a word-order arrow flips 'shoes shiny' to 'shiny shoes'."},{"time":"02:30–02:55","narration":"Publish: Omar draws himself in his Eid clothes and labels them. Eid Mubarak!","on_screen":"5 Publish 🎉","visual":"A class display 'Our Eid Clothes' fills with drawings."}],"captions_ar":["عيد مبارك! يريد عمر أن يصف ملابس العيد.","خطط بالهامبرغر: الخبزة العليا جملة الموضوع، والطبقات التفاصيل، والخبزة السفلى الخاتمة.","المسودة: في العيد ألبس ملابسي الجديدة. ألبس ثوبًا أبيض طويلًا. عندي حذاء جلدي أسود لامع…","التحسين: أضف صفة! ألبس جوارب بيضاء ناعمة لأن حذائي الجديد قاسٍ.","التدقيق: حرف E كبير في Eid، وحرف I كبير، والنقاط، والصفات قبل الأسماء.","النشر: يرسم عمر نفسه بملابس العيد ويكتب أسماءها. عيد مبارك!"],"voice":"Narrator: American English, warm female teacher, speed 0.85. Omar reads his Eid description with excitement."},"texts":[],"activities":[{"id":"RW-L02-U4-LS5-A1","type":"mcq","stage":"controlled","instructions":"Controlled practice: Choose the best answer.","instructions_ar":"اختر أفضل إجابة.","items":[{"q":"Which is the best topic sentence for *What I Wear on Eid*?","answer":"On Eid, I wear my new clothes.","explanation":"It tells what the writing is about.","explanation_ar":"تخبر عن موضوع الكتابة.","options":["On Eid, I wear my new clothes.","I have a cat.","Eid.","My shoes are black."],"dok":1,"skill":"topic sentence","stage":"controlled"},{"q":"In the Hamburger Plan, the layers in the middle are the ___.","answer":"details","explanation":"Layers = details.","explanation_ar":"التفاصيل.","options":["topic sentence","closing","details","title"],"dok":1,"skill":"organization","stage":"controlled"},{"q":"Which closing sentence ends an Eid description well?","answer":"I feel very happy in my Eid clothes!","explanation":"A feeling to finish.","explanation_ar":"جملة شعور ختامية.","options":["I wear a thobe.","On Eid, I wear new clothes.","My socks are white.","I feel very happy in my Eid clothes!"],"dok":1,"skill":"closing","stage":"controlled"},{"q":"*My shoes are bright, with light on them.* They are ___.","answer":"shiny","explanation":"Shiny = bright.","explanation_ar":"لامعة.","options":["soft","wooden","shiny","loose"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"*You look neat and nice in your thobe.* You look ___.","answer":"smart","explanation":"Smart = neat and nice.","explanation_ar":"أنيق.","options":["smart","boring","snowy","thick"],"dok":1,"skill":"vocabulary","stage":"controlled"},{"q":"Which Eid detail sentence uses *so* correctly?","answer":"My dress is new, so I feel excited.","explanation":"Comma before so + effect.","explanation_ar":"فاصلة قبل so.","options":["My dress is new so, I feel excited.","My dress is new, so I feel excited.","So my dress is new, I feel excited.","My dress so is new."],"dok":2,"skill":"cause and effect","stage":"controlled"}]},{"id":"RW-L02-U4-LS5-A2","type":"sequence","stage":"guided","instructions":"Put in order: Put the sentences or words in order.","instructions_ar":"رتّب الجمل أو الكلمات.","items":[{"q":"Order Omar's Eid description.","answer":"On Eid, I wear my new clothes. → I wear a long white thobe. → I have shiny black shoes. → I feel very happy!","explanation":"Topic sentence → details → closing.","explanation_ar":"جملة الموضوع ← التفاصيل ← الخاتمة.","stage":"guided","parts":["I have shiny black shoes.","On Eid, I wear my new clothes.","I wear a long white thobe.","I feel very happy!"],"target":["On Eid, I wear my new clothes.","I wear a long white thobe.","I have shiny black shoes.","I feel very happy!"]},{"q":"Build a detail about a green dress.","answer":"I wear a long green dress.","explanation":"Size → color → noun.","explanation_ar":"حجم ← لون ← اسم.","stage":"guided","parts":["dress.","wear","a","long","I","green"],"target":["I","wear","a","long","green","dress."]},{"q":"Build a detail about Eid shoes.","answer":"I have shiny black leather shoes.","explanation":"Describing words before shoes.","explanation_ar":"الصفات قبل shoes.","stage":"guided","parts":["leather","black","shiny","shoes.","have","I"],"target":["I","have","shiny","black","leather","shoes."]},{"q":"Build a topic sentence about Eid.","answer":"On Eid, I wear my new clothes.","explanation":"Topic sentence with a comma after Eid.","explanation_ar":"جملة الموضوع.","stage":"guided","parts":["clothes.","my","wear","On","Eid,","I","new"],"target":["On","Eid,","I","wear","my","new","clothes."]},{"q":"Build a because sentence about socks.","answer":"I wear soft socks because my shoes are hard.","explanation":"Detail + because + reason.","explanation_ar":"تفصيل + because + سبب.","stage":"guided","parts":["my shoes","are hard.","because","I wear","soft socks"],"target":["I wear","soft socks","because","my shoes","are hard."]},{"q":"Build a closing sentence.","answer":"I look smart in my Eid clothes!","explanation":"Closing feeling sentence.","explanation_ar":"جملة ختامية.","stage":"guided","parts":["look","in","smart","I","my","Eid","clothes!"],"target":["I","look","smart","in","my","Eid","clothes!"]}]},{"id":"RW-L02-U4-LS5-A3","type":"organizer","stage":"freer","instructions":"Organizer: Plan your Hamburger.","instructions_ar":"خطط للهامبرغر.","items":[{"q":"Top bun – write your topic sentence.","answer":"On Eid, I wear my beautiful new clothes.","explanation":"Tells the topic.","explanation_ar":"تخبر بالموضوع.","dok":1,"skill":"planning","stage":"freer"},{"q":"Layers – list four clothes items with two describing words each.","answer":"a long white thobe; a red and white shemagh; shiny black shoes; soft white socks","explanation":"Two describing words each.","explanation_ar":"صفتان لكل قطعة.","dok":2,"skill":"planning","stage":"freer"},{"q":"Which layer will have because or so? Write it.","answer":"I wear soft socks because my new shoes are hard.","explanation":"One because/so sentence.","explanation_ar":"جملة بـ because أو so.","dok":2,"skill":"planning","stage":"freer"},{"q":"Bottom bun – write your closing.","answer":"I feel smart and happy on Eid!","explanation":"A feeling sentence.","explanation_ar":"جملة شعور.","dok":1,"skill":"planning","stage":"freer"}]},{"id":"RW-L02-U4-LS5-A4","type":"writing","stage":"production","instructions":"Writing: Write your description. Then revise, edit and publish it.","instructions_ar":"اكتب وصفك ثم حسّنه ودققه وانشره.","items":[{"q":"Write your topic sentence and your first two details.","answer":"On Eid, I wear my new clothes. I wear a long white thobe. I put on a red and white shemagh.","explanation":"Topic sentence + 2 details.","explanation_ar":"جملة موضوع + تفصيلان.","dok":2,"skill":"writing","stage":"production"},{"q":"Write two more details. Use because or so in one of them.","answer":"I have shiny black leather shoes. I wear soft white socks because my new shoes are hard.","explanation":"2 details + because/so.","explanation_ar":"تفصيلان + because/so.","dok":2,"skill":"writing","stage":"production"},{"q":"Write your closing sentence about how you feel on Eid.","answer":"I look smart in my Eid clothes, and I feel very happy!","explanation":"Feeling sentence.","explanation_ar":"جملة شعور.","dok":1,"skill":"writing","stage":"production"},{"q":"Write one describing word your partner added. Did you keep it? Why?","answer":"My partner added 'shiny'. I kept it because my shoes are really shiny.","explanation":"Revision decision + because.","explanation_ar":"قرار التحسين + because.","dok":3,"skill":"revising","stage":"production","_w":{"checklist":[],"min":null,"max":null}}]},{"id":"RW-L02-U4-LS5-ORG","type":"organizer","organizer":"Hamburger Plan","instructions":"Organizer: Write your topic sentence on the top bun, one detail on each layer and your closing on the bottom bun.","items":[{"q":"Top bun – topic sentence","answer":"On Eid, I wear my new clothes."},{"q":"Layer 1 – detail","answer":"a long white thobe"},{"q":"Layer 2 – detail","answer":"a red and white shemagh"},{"q":"Layer 3 – detail","answer":"shiny black leather shoes"},{"q":"Layer 4 – detail (because or so)","answer":"soft white socks because my shoes are hard"},{"q":"Bottom bun – closing","answer":"I look smart and I feel very happy!"}]},{"id":"RW-L02-U4-LS5-WR","type":"writing","instructions":"Writing: Write \"What I Wear on Eid\": 6 describing sentences with a topic sentence, details and a closing. Write \"What I Wear on Eid\": 6 describing sentences with a topic sentence, details and a closing.","instructions_ar":"اكتب «ما ألبسه في العيد»: 6 جمل وصفية فيها جملة موضوع وتفاصيل وخاتمة.","prompt":"Write \"What I Wear on Eid\": 6 describing sentences with a topic sentence, details and a closing.","checklist":["I wrote a topic sentence.","I wrote four details about my clothes.","My describing words come before the nouns.","I did not add -s to describing words.","I used because or so one time.","I wrote a closing feeling sentence.","Eid, I and the first word of each sentence have capitals; sentences end with . or !"],"rubric_id":"RW-RUBRIC-5T","min_words":40,"max_words":100,"organizer":"Hamburger Plan (topic sentence – details – closing)","items":[{"q":"Write \"What I Wear on Eid\": 6 describing sentences with a topic sentence, details and a closing.","answer":"On Eid, I wear my new clothes. I wear a long white thobe. I put on a red and white shemagh. I have shiny black leather shoes. I wear soft white socks because my new shoes are hard. I look smart in my Eid clothes, and I feel very happy!","_w":{"checklist":["I wrote a topic sentence.","I wrote four details about my clothes.","My describing words come before the nouns.","I did not add -s to describing words.","I used because or so one time.","I wrote a closing feeling sentence.","Eid, I and the first word of each sentence have capitals; sentences end with . or !"],"min":40,"max":100}}]}],"game":{"name":"Build-a-Burger","mechanic":"timed_quiz","rules":["On this screen: answer the lesson questions as fast as you can.","In class: Burger stack: sentence pieces slide in; the child stacks them in the right place and taps any piece with a word-order mistake to fix it. A perfect burger gets a 'Chef Writer' badge.","Teams get a mixed pile of burger pieces for two descriptions (Eid clothes and school uniform).","Teams build two burgers in the right order.","Teams find and fix the pieces with mistakes (a thobe white → a white thobe).","Teams read one burger aloud.","Correct burger = 3 points; each fixed mistake = 1 point."],"data":[]},"exit_quiz":[{"q":"What does a description help the reader do?","answer":"see something in their mind","explanation":"Description = picture in the mind.","explanation_ar":"يتخيل الشيء.","options":["play a game","follow steps","see something in their mind","answer a letter"],"dok":1,"skill":"genre"},{"q":"In the Hamburger Plan, the top bun is the ___.","answer":"topic sentence","explanation":"Top bun = topic sentence.","explanation_ar":"جملة الموضوع.","options":["closing","topic sentence","first detail","drawing"],"dok":1,"skill":"organization"},{"q":"Which detail sentence about Eid shoes is correct?","answer":"I have shiny new shoes.","explanation":"Describing words before shoes.","explanation_ar":"صحيحة.","options":["I have shoes shiny new.","I have shinys shoes.","I has shiny shoes.","I have shiny new shoes."],"dok":1,"skill":"word order"},{"q":"Which word must ALWAYS start with a capital letter?","answer":"Eid","explanation":"Eid is the name of a holiday.","explanation_ar":"Eid.","options":["shoes","Eid","white","clothes"],"dok":1,"skill":"capitals"},{"q":"*Add a detail about your scarf.* A detail is ___.","answer":"a small piece of information","explanation":"Detail = small piece of information.","explanation_ar":"تفصيل.","options":["a small piece of information","the title","the last word","a drawing"],"dok":1,"skill":"vocabulary"},{"q":"Fix it: *My new shoes is black.*","answer":"My new shoes are black.","explanation":"Shoes → are.","explanation_ar":"are.","options":["My shoes new is black.","My new shoe are black.","My new shoes black is.","My new shoes are black."],"dok":2,"skill":"editing"},{"q":"Which detail gives a REASON with *because*?","answer":"I wear a jacket because Eid morning is cool.","explanation":"because + complete reason.","explanation_ar":"سبب كامل.","options":["I wear a jacket because Eid morning is cool.","I wear a jacket.","Because the jacket.","The jacket is gray because."],"dok":2,"skill":"cause and effect"},{"q":"Which sentence would make the BEST closing for an Eid description?","answer":"Eid is my favorite day, and I love my new clothes!","explanation":"A feeling to finish.","explanation_ar":"خاتمة بشعور.","options":["I have socks.","First, put on your thobe.","Where is my shemagh?","Eid is my favorite day, and I love my new clothes!"],"dok":2,"skill":"closing"},{"q":"Your partner adds *shiny* to *black shoes*. Where does it go?","answer":"shiny black shoes","explanation":"Describing words before the noun.","explanation_ar":"قبل الاسم.","options":["shiny black shoes","black shiny shoes shoes","black shoes shiny","shoes shiny black"],"dok":2,"skill":"revising"},{"q":"Which description of Eid clothes is the most complete?","answer":"a topic sentence, four details with describing words, a because sentence and a closing","explanation":"It has all the parts.","explanation_ar":"فيه كل الأجزاء.","options":["two sentences with no describing words","a list of clothes names only","a topic sentence, four details with describing words, a because sentence and a closing","a closing sentence only"],"dok":3,"skill":"evaluate"}],"images":[{"id":"IMG-RW-L02-U4-LS5-V01","prompt":"Picture for the word 'Eid': a family in new clothes greeting each other"},{"id":"IMG-RW-L02-U4-LS5-V02","prompt":"Picture for the word 'new': a shoe box with shiny new shoes"},{"id":"IMG-RW-L02-U4-LS5-V03","prompt":"Picture for the word 'shiny': shiny black shoes with a sparkle"},{"id":"IMG-RW-L02-U4-LS5-V04","prompt":"Picture for the word 'smart': a boy in a neat thobe smiling at a mirror"},{"id":"IMG-RW-L02-U4-LS5-V05","prompt":"Picture for the word 'topic sentence': the top bun of a burger labelled 'topic sentence'"},{"id":"IMG-RW-L02-U4-LS5-V06","prompt":"Picture for the word 'detail': burger layers labelled 'detail'"},{"id":"IMG-RW-L02-U4-LS5-V07","prompt":"Picture for the word 'closing': the bottom bun of a burger labelled 'closing'"},{"id":"IMG-RW-L02-U4-LS5-01","prompt":"Omar in his Eid thobe and shemagh in front of a mirror."},{"id":"IMG-RW-L02-U4-LS5-02","prompt":"A hamburger organizer with labels for topic sentence, details and closing."},{"id":"IMG-RW-L02-U4-LS5-03","prompt":"A classroom board with drawings of Eid clothes."}],"audio":[{"id":"AUD-RW-L02-U4-LS5-V01","script":"Eid. We wear new clothes on Eid."},{"id":"AUD-RW-L02-U4-LS5-V02","script":"new. I have new shoes for Eid."},{"id":"AUD-RW-L02-U4-LS5-V03","script":"shiny. My shoes are shiny."},{"id":"AUD-RW-L02-U4-LS5-V04","script":"smart. You look smart in your thobe!"},{"id":"AUD-RW-L02-U4-LS5-V05","script":"topic sentence. My topic sentence is: On Eid, I wear my new clothes."},{"id":"AUD-RW-L02-U4-LS5-V06","script":"detail. Add a detail about your shoes."},{"id":"AUD-RW-L02-U4-LS5-V07","script":"closing. My closing is: I love Eid!"},{"id":"AUD-RW-L02-U4-LS5-VID","script":"Eid Mubarak! Omar wants to describe his Eid clothes. Plan with a hamburger! Top bun: topic sentence. Layers: details. Bottom bun: closing. Draft: On Eid, I wear my new clothes. I wear a long white thobe. I have shiny black leather shoes… Revise: add a describing word! I wear socks… I wear SOFT WHITE socks because my new shoes are hard. Edit: capital E for Eid, capital I, periods – check! Describing words before nouns – check! Publish: Omar draws himself in his Eid clothes and labels them. Eid Mubarak!"}]}],"unit_test":[{"q":"You wear a ___ around your neck on a cold day.","answer":"scarf","explanation":"A scarf goes around your neck.","explanation_ar":"وشاح.","options":["sock","shoe","uniform","scarf"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Before you sleep, you ___ your school uniform.","answer":"take off","explanation":"Before sleeping → take off.","explanation_ar":"تخلع.","options":["put on","wear","take off","describe"],"dok":1,"skill":"phrasal verbs","_part":"Part A – Words"},{"q":"Mom makes the shirts small and neat. She ___ them.","answer":"folds","explanation":"Fold = make neat.","explanation_ar":"تطويها.","options":["kicks","rolls","folds","scores"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Which word tells the MATERIAL of a jacket?","answer":"leather","explanation":"Leather is a material.","explanation_ar":"جلد.","options":["leather","black","short","new"],"dok":1,"skill":"describing words","_part":"Part A – Words"},{"q":"Your socks are not dirty. They are ___.","answer":"clean","explanation":"Not dirty = clean.","explanation_ar":"نظيفة.","options":["clean","loose","thick","boring"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"Which phrase about a cap has the describing words in the right order?","answer":"a small red cotton cap","explanation":"Size → color → material.","explanation_ar":"حجم ← لون ← مادة.","options":["a cotton red small cap","a small red cotton cap","a red cotton small cap","a cap small red cotton"],"dok":2,"skill":"adjective order","_part":"Part A – Words"},{"q":"In Canada, people wear ___ on their hands in the snow.","answer":"gloves","explanation":"Gloves are for hands.","explanation_ar":"قفازات.","options":["boots","gloves","hats","thobes"],"dok":1,"skill":"vocabulary","_part":"Part A – Words"},{"q":"*In my opinion, gray is the best color.* *Opinion* tells ___.","answer":"what the writer thinks","explanation":"Opinion = what you think.","explanation_ar":"ما يعتقده الكاتب.","options":["a fact from a book","the size of a shirt","the material","what the writer thinks"],"dok":2,"skill":"vocabulary in context","_part":"Part A – Words"},{"q":"Which sentence about a uniform has the right word order?","answer":"I wear a clean gray uniform.","explanation":"Describing words before the noun.","explanation_ar":"الصفات قبل الاسم.","options":["I wear a uniform gray clean.","I wear a clean gray uniform.","I wear a gray clean uniforms.","I wear uniform a gray."],"dok":1,"skill":"word order","_part":"Part D – Check the sentences"},{"q":"Which word joins a cause to its EFFECT? *It is raining, ___ I wear boots.*","answer":"so","explanation":"so + effect.","explanation_ar":"so.","options":["because","but","or","so"],"dok":1,"skill":"cause and effect","_part":"Part D – Check the sentences"},{"q":"Which question asks for a REASON?","answer":"Why do you wear a hat?","explanation":"Why = reason.","explanation_ar":"Why.","options":["Where is your hat?","Who has a hat?","Why do you wear a hat?","What color is your hat?"],"dok":1,"skill":"question words","_part":"Part D – Check the sentences"},{"q":"Fix it: *Grandpa wears a thobe white long.*","answer":"Grandpa wears a long white thobe.","explanation":"Size → color → noun.","explanation_ar":"حجم ← لون ← اسم.","options":["Grandpa wears a long white thobe.","Grandpa wears a white thobe long.","Grandpa wear a long white thobes.","Grandpa long white wears a thobe."],"dok":2,"skill":"editing","_part":"Part D – Check the sentences"},{"q":"Which sentence about boots has the comma in the right place?","answer":"My boots are muddy, so I take them off.","explanation":"Comma before so.","explanation_ar":"الفاصلة قبل so.","options":["My boots are muddy so, I take them off.","My boots, are muddy so I take them off.","My boots are muddy, so I take them off.","My boots are, muddy so I take them off."],"dok":2,"skill":"punctuation","_part":"Part D – Check the sentences"}],"unit_writing":{"task":"Describe your school uniform or your favorite clothes in 5–6 sentences. Use describing words before nouns and one sentence with because or so.","model":"I wear my school uniform from Sunday to Thursday. I wear a clean white cotton shirt. I have long gray pants. My shoes are black and shiny. I wear a thick navy jacket in winter because Taif is cold in the morning. I look smart in my uniform!","marks":20}});
